ERDATA["abilities"]=[["0","-------","------","------",[]],["1","Stench","恶臭","10%几率使目标畏缩.剧毒地形永久存在.\n攻击获得+10%的畏缩几率.连续攻击技能的每一击单独计算畏缩几率.当该宝可梦在场时,剧毒地形的回合数不会减少.",[]],["2","Drizzle","降雨","出场时降下雨水,持续8回合.\n降雨特性会在宝可梦进入战斗时降下雨水,持续8回合（携带潮湿岩石时为12回合）.雨天使水系招式威力提升50%,火系伤害降低50%.部分招式和特性在雨天下有特殊效果.无法覆盖原始天气.",["天气手·雨"]],["3","Speed Boost","加速","每回合结束后自身速度提升1级.\n该宝可梦每在场完成一个完整的回合,其速度在回合结束时提升1级.入场的当回合不会触发.",[]],["4","Battle Armor","战斗盔甲","免疫击中要害.受到的招式伤害降低20%.\n受到的伤害降低20%（x0.8）,与其他减伤效果乘法叠加.此外,免疫击中要害,会心一击将作为普通攻击处理,并且不会触发攻击要害的效果（例如“至骨”的流血效果）.",[]],["5","Sturdy","结实","满HP时,不会一击濒死,必定留下1点HP.\n当该宝可梦HP全满时,能够承受任何一次攻击并至少留下1点HP.此效果如同携带了气势披带,因此无法抵御连续攻击技能或后续攻击（例如“余震”、“雷召”）.",[]],["6","Damp","湿气","使接触到的对手变为水属性.攻击时也生效.\n如果该宝可梦与另一只宝可梦发生接触（无论是攻击方还是防御方）,对方的属性会变为纯水属性.此效果在连续招式或优先度招式命中时立即发生,可以在对手的连续攻击过程中消除其本系加成.",[]],["7","Limber","柔软","免疫麻痹,反伤减半,免疫自身能力降低.\n该宝可梦受到的所有反伤伤害减半；包括具有比例反伤的招式（如勇鸟猛攻）、具有撞伤风险的招式（如飞膝踢）、或固定反伤的招式（如钢炮光线）.麻痹状态无法影响该宝可梦,且获得此特性时,若已处于麻痹状态则会立刻治愈.",[]],["8","Sand Veil","沙隐","在沙暴中,闪避率提升1.25倍.\n在沙暴中,对手的命中率变为原来的1/1.25,且自身免疫沙暴伤害.会被无防御或破格特性识破.",[]],["9","Static","静电","接触攻击有30%几率麻痹,非接触攻击有10%几率麻痹.\n无论该宝可梦是攻击方还是被攻击方,都有几率使对手陷入麻痹.非接触攻击有10%几率麻痹,接触攻击有30%几率麻痹.",[]],["10","Volt Absorb","蓄电","受到电属性招式攻击时,恢复最大HP的25%.\n该宝可梦能够吸收电属性招式,将其转化为能量,恢复其最大HP的25%.对电属性伤害及其附加效果（如电磁波的麻痹）完全免疫.对于水/飞行属性宝可梦来说,是消除4倍电系弱点的完美选择.",["免疫·电"]],["11","Water Absorb","储水","受到水属性招式攻击时,恢复最大HP的25%.\n该宝可梦免疫水属性招式,并且受到水属性招式攻击时会恢复其最大HP的25%.",["免疫·水","雨天免疫位"]],["12","Oblivious","迟钝","免疫着迷、惊吓、威吓和挑衅.\n该宝可梦免疫着迷、惊吓、威吓和挑衅.在获得此特性时,如果已经处于上述任意状态,则会立刻解除.",[]],["13","Cloud Nine","无关天气","清除天气并阻止其效果产生.\n上场时清除所有天气,并且在该宝可梦在场期间使所有天气效果（包括原始天气）失效.天气仍可以被设置,但在该宝可梦下场前,不会提供任何伤害加成或触发与天气相关的特性.",[]],["14","Compound Eyes","复眼","获得1.3倍的命中率提升.\n该宝可梦的招式命中率变为1.3倍.",[]],["15","Insomnia","不眠","不会陷入睡眠状态.使用睡觉会失败.\n防止任何方式陷入睡眠状态,包括催眠招式、特性（如哈欠）以及其他可能导致睡眠的效果.使用招式睡觉将完全失败.若在获得此特性前已处于睡眠状态（例如通过烦恼种子或特性交换）,则会立刻醒来.可被破格等特性识破",[]],["16","Color Change","变色","受到攻击前,变为拥有抗性或免疫的属性.\n受到伤害前,将自身转变为防御效果最佳的纯属性.优先考虑免疫而非抗性.每回合仅触发一次.",[]],["17","Immunity","免疫","不会陷入中毒状态.受到的毒属性伤害减半.\n防止中毒.所有毒属性伤害减半.与其他减伤效果乘法叠加.获得此特性时若已中毒,则立刻治愈.",["减伤·毒"]],["18","Flash Fire","引火","受到火属性招式攻击后,自身火属性招式威力提升至1.5倍.\n引火特性使宝可梦完全免疫火属性招式.受到火属性攻击后,自身的火属性招式威力提升50%,直到下场为止.多次被火属性攻击命中不会使效果叠加.",["免疫·火","晴天免疫位"]],["19","Shield Dust","鳞粉","免疫招式的追加效果、场地状态和粉末类招式.\n阻挡所有攻击招式的追加效果.免疫所有入场陷阱.免疫所有粉末类招式,包括催眠粉、麻痹粉、毒粉、蘑菇孢子、棉孢子、愤怒粉、粉末和魔法粉.",[]],["20","Own Tempo","我行我素","免疫混乱、威吓和惊吓.\n免疫混乱、威吓和惊吓.获得此特性时若已混乱,则立刻解除混乱状态.",[]],["21","Suction Cups","吸盘","不会被对手的招式强制替换下场.\n防止被招式或红牌强制替换下场.",[]],["22","Intimidate","威吓","出场时,降低所有对手的攻击1级.\n进入战斗时,降低所有对手宝可梦的攻击1级.",["出场降攻·威吓"]],["23","Shadow Tag","踩影","踩住对手的影子使其无法逃走或替换。幽灵属性宝可梦不受影响",["踩影陷阱"]],["24","Rough Skin","粗糙皮肤","使用接触类招式的敌人会损失1/8的最大HP.\n对使用接触类招式的攻击者造成其最大HP1/8的伤害.对于连续攻击招式,每次命中都会触发.",[]],["25","Wonder Guard","神奇守护","仅会受到效果绝佳的攻击或间接伤害.\n只有效果绝佳的招式或间接伤害能够伤害到该宝可梦.其他所有直接攻击造成的伤害均为零.中毒或特性伤害等其他来源的伤害照常生效.",[]],["26","Levitate","飘浮","免疫地面属性招式.自身飞行招式威力提升至1.25倍.\n该宝可梦免疫地面属性招式以及其他地面效果,如撒菱和场地状态.飞行属性招式伤害提升25%.",["免疫·地面","地面免疫位"]],["27","Effect Spore","孢子","受到接触类招式攻击时,30%几率使攻击者陷入睡眠、麻痹或中毒状态.\n受到接触类招式攻击时,有30%的几率使攻击者陷入睡眠、麻痹或中毒状态.状态类型随机选择.",[]],["28","Synchronize","同步","受到异常状态时，使攻击者也获得相同的异常状态\n当被施加非瞬间异常状态（睡眠除外）时,攻击者也会陷入相同的状态.此效果可穿透替身.若该宝可梦在被施加异常状态时能够治愈自身,则会在治愈前先将异常状态施加给攻击者.",[]],["29","Clear Body","恒净之躯","免疫能力降低.\n免疫所有由招式或特性引起的能力降低效果.包括因使用过热等招式导致的自身能力降低.",[]],["30","Natural Cure","自然回复","替换下场时,治愈异常状态.\n替换下场时,治愈所有异常状态.",[]],["31","Lightning Rod","避雷针","吸引电属性招式.并提升自身最高的攻击能力.\n该宝可梦会吸引电属性招式,并对其免疫.此外,受到电属性招式攻击后,自身最高的攻击能力提升1级.",["免疫·电"]],["32","Serene Grace","天恩","自身招式的追加效果触发几率加倍.\n自身攻击招式的追加效果触发几率加倍.",[]],["33","Swift Swim","悠游自如","下雨天气时,该宝可梦的速度提升至1.5倍.\n下雨天气时,速度提升50%.",["雨天速度位（×1.5）"]],["34","Chlorophyll","叶绿素","大晴天天气时,该宝可梦的速度提升至1.5倍.\n大晴天天气时,速度提升50%.",["晴天速度位（×1.5）"]],["35","Illuminate","发光","获得1.2倍的命中率提升.\n该宝可梦的招式命中率变为1.2倍.攻击命中时,移除目标的幽灵属性.",[]],["36","Trace","复制","复制对手的特性.无法复制先天特性.\n进入战斗时,复制一只对手宝可梦的特性,替换当前特性栏位中的特性.无法复制复制、神奇守护以及大多数与形态相关的特性.在双打对战中,随机选择首个符合条件的对手.",[]],["37","Huge Power","大力士","自身的攻击能力加倍.提升最终能力值而非基础能力值.\n该宝可梦的攻击能力值变为2倍与其他伤害加成效果乘法叠加.",[]],["38","Poison Point","毒刺","接触攻击有30%几率使目标中毒.攻击时也生效.\n无论该宝可梦是攻击方还是被攻击方,使用接触类招式时有30%的几率使对手中毒.",[]],["39","Inner Focus","精神力","不会陷入畏缩状态,免疫威吓和惊吓.真气弹必中.\n真气弹必定命中.不受畏缩、威吓或惊吓的影响.",[]],["40","Magma Armor","熔岩铠甲","免疫冻伤.受到的水系和冰系招式伤害降低30%.\n免疫冻伤状态.受到的水属性和冰属性招式伤害降低30%.与其他减伤效果乘法叠加.",[]],["41","Water Veil","水幕","免疫灼伤.出场时制造出水环.\n出场时制造出水环,每回合回复1/16的HP.免疫灼伤状态,并在替换上场时解除灼伤状态.",[]],["42","Magnet Pull","磁力","钢属性宝可梦无法逃走幽灵属性不受影响.\n在该宝可梦在场期间,阻止钢属性宝可梦替换下场.幽灵属性免疫此效果.携带逃脱按键或使用替换招式（如快速折返）的宝可梦可以逃脱如果在战斗中中途替换上场,效果将在下一回合生效.",["捕钢陷阱"]],["43","Soundproof","隔音","免疫声音类招式.\n免疫声音类招式.以自身为目标的声音类招式不受影响.",[]],["44","Rain Dish","雨盘","下雨天气时,每回合回复1/8的最大HP.\n下雨天气时,每回合结束时回复1/8的最大HP.",[]],["45","Sand Stream","扬沙","出场时引发沙暴,持续8回合.\n出场时引发沙暴,持续8回合（携带光滑岩石时为12回合）.每回合对非岩石/地面/钢属性宝可梦造成1/16的HP伤害岩石属性宝可梦的特防提升50%.使与大晴天相关的招式效果减半",["天气手·沙"]],["46","Pressure","压迫感","对手招式PP消耗翻倍.出场时清除对手的能力提升.\n对手使用招式时,PP消耗加倍.出场时,清除所有对手的能力提升等级.",[]],["47","Thick Fat","厚脂肪","受到的火属性和冰属性招式伤害减半.\n受到的火属性和冰属性招式伤害降低50%.与其他减伤效果乘法叠加.",["减伤·火","减伤·冰"]],["48","Early Bird","早起","即使变为睡眠状态，也能以2倍的速度提早醒来。",[]],["49","Flame Body","火焰之躯","接触攻击有30%几率灼伤,非接触20%.主动攻击时也生效.\n与该宝可梦发生接触有30%几率使对手灼伤.非接触攻击有20%几率.无论攻击方还是被攻击方均会生效.",[]],["50","Run Away","逃跑","从野生宝可梦那儿必定逃走；如果被对方下降能力，速度提升一段",[]],["51","Keen Eye","锐利目光","免疫命中率降低.获得1.2倍的命中率提升.\n防止命中率能力等级被降低.所有招式获得1.2倍的命中率提升.",[]],["52","Hyper Cutter","怪力钳","不会被对手降低攻击，接触类招式命中要害率+1",[]],["53","Pickup","捡拾","出场时移除所有场地状态.但不会免疫场地状态伤害.\n进入战斗时,清除己方场地上所有入场陷阱.该宝可梦在清除陷阱时仍会受到它们的影响.",[]],["54","Truant","懒惰","无法连续使用攻击招式.\n防止连续使用攻击招式.使用攻击招式后,下一回合必须偷懒,无法攻击.使用变化招式不受影响.",[]],["55","Hustle","活力","命中率0.9倍.伤害提升至1.4倍.\n攻击招式威力提升40%,但命中率降低10%.仅影响非变化招式.",[]],["56","Cute Charm","迷人之躯","接触时有50%几率使对手着迷.主动攻击时也生效.\n当通过接触受到攻击时（无论攻击方还是被攻击方）,有50%几率使攻击者陷入着迷状态（使其攻击和特攻减半）.此效果仅对异性宝可梦生效.",[]],["57","Plus","正电","如果同伴宝可梦具有负电或正电,造成双倍伤害.\n当与具有负电或正电的同伴一起出战时,该宝可梦的输出威力加倍.",[]],["58","Minus","负电","如果同伴宝可梦具有负电或正电,造成双倍伤害.\n当与具有负电或正电的同伴一起出战时,该宝可梦的输出威力加倍.",[]],["59","Forecast","阴晴不定","受天气的影响改变形态，自身使用改变天气的招式时释放气象球",[]],["60","Sticky Hold","黏着","不会失去携带的物品.\n该宝可梦携带的物品不会被强制移除或偷走.",[]],["61","Shed Skin","蜕皮","每回合结束时,有30%几率治愈自身的异常状态.\n每回合结束时,该宝可梦有30%的几率治愈自身所受到的异常状态.",[]],["62","Guts","毅力","处于异常状态时,攻击提升至1.5倍.\n处于任何异常状态时,攻击能力值提升50%.并且无视灼伤状态带来的攻击力降低效果.",[]],["63","Marvel Scale","神奇鳞片","处于异常状态时,防御提升至1.5倍.\n处于任何异常状态时,基础防御能力值提升50%.",["异常受益"]],["64","Liquid Ooze","污泥浆","吸取招式会对使用者造成伤害而非治疗.\n污泥浆特性会反转所有吸取招式的治疗效果,使攻击者受到伤害.影响吸取拳、超级吸取、终极吸取、吸血以及类似的吸取类攻击伤害量等于原本应恢复的HP.完美克制依赖治疗的战术.",[]],["65","Overgrow","茂盛","草属性招式威力提升至1.2倍,HP低于1/3时提升至1.5倍.\n草属性招式威力提升20%,当HP低于1/3时提升50%.",["输出位·草"]],["66","Blaze","猛火","火属性招式威力提升至1.2倍,HP低于1/3时提升至1.5倍.\n火属性招式威力提升20%,当HP低于1/3时提升50%.",["输出位·火"]],["67","Torrent","激流","水属性招式威力提升至1.2倍,HP低于1/3时提升至1.5倍.\n水属性招式威力提升20%,当HP低于1/3时提升50%.",["输出位·水"]],["68","Swarm","虫之预感","虫属性招式威力提升至1.2倍,HP低于1/3时提升至1.5倍.\n虫属性招式威力提升20%,当HP低于1/3时提升50%.",["输出位·虫"]],["69","Rock Head","坚硬脑袋","免疫反伤伤害,但不免疫大爆炸/撞击伤害.\n防止所有来自自身招式或特性的反伤伤害.同时免疫因愤怒产生的反伤伤害无法防止撞击伤害或大爆炸/自爆的伤害.",[]],["70","Drought","日照","出场时，会将天气变为晴天，持续8回合",["天气手·晴"]],["71","Arena Trap","沙穴","敌人无法逃走.幽灵属性和飘浮状态的宝可梦免疫.\n防止所有非飘浮状态或非幽灵属性的对手替换下场.携带逃脱按键或使用替换招式（如快速折返）的宝可梦可以逃脱如果在战斗中中途替换上场,效果将在下一回合生效.",["沙穴陷阱"]],["72","Vital Spirit","干劲","不会陷入睡眠.使用格斗属性招式治愈异常状态.\n免疫睡眠状态.当该宝可梦使用格斗属性招式时在招式效果结束后立即治愈所有异常状态.获得此特性时若已睡眠,则立刻解除.",[]],["73","White Smoke","白色烟雾","入场释放3回合白色烟雾，白烟下不会被对手降能力且对手命中-25%",[]],["74","Pure Power","瑜伽之力","自身的特攻能力加倍.提升最终能力值,而非基础能力值.\n该宝可梦的攻击能力值变为2倍与其他伤害加成效果乘法叠加.",[]],["75","Shell Armor","硬壳盔甲","免疫击中要害.受到的招式伤害降低20%.\n受到的伤害降低20%（x0.8）,与其他减伤效果乘法叠加.此外,免疫击中要害,会心一击将作为普通攻击处理,并且不会触发攻击要害的效果（例如“至骨”的流血效果）.",[]],["76","Air Lock","气闸","无关天气 + 吹气筒.\n出场时设置顺风,持续3回合,并清除所有天气效果.原始天气会被压制.在该宝可梦在场期间,天气仍可被设置,但不会产生任何效果,直到该宝可梦下场.",[]],["77","Tangled Feet","蹒跚","处于混乱或愤怒状态时,使用速度进行防御.\n当该宝可梦处于混乱或愤怒状态时,在伤害计算中使用其速度能力值来代替防御或特防.讲究围巾的效果不会影响此特性",[]],["78","Motor Drive","电气引擎","受到电属性招式攻击时,提升速度而非受到伤害.\n免疫电属性招式,并且在受到电属性招式攻击时,速度提升1级.对于连续攻击招式,每次命中都会触发.",["免疫·电"]],["79","Rivalry","斗争心","对同性对手造成1.25倍伤害.受到异性对手的伤害为0.75倍.\n该宝可梦对同性别的对手造成伤害提高25%,受到异性别的对手造成的伤害降低25%.对无性别的宝可梦无效.",[]],["80","Steadfast","不屈之心","如果该宝可梦畏缩,速度提升1级.\n当陷入畏缩状态时,速度提升1级.",[]],["81","Snow Cloak","雪隐","在冰雹中,闪避率提升至1.25倍.",[]],["82","Gluttony","贪吃鬼","提早吃树果.树果还会额外回复1/3的最大HP.\n原本在HP低于1/4时发动的树果,改为在HP低于1/2时发动.此外,在消耗任何树果后,该宝可梦会额外回复1/3的最大HP.不包括通过啄食等招式消耗的树果.",[]],["83","Anger Point","愤怒穴位","受到攻击时,攻击提升1级.受到击中要害的攻击时提升至最大.\n受到攻击时,该宝可梦的攻击提升1级；若受到击中要害的攻击,则攻击能力值提升至最大.对于连续攻击招式,每次命中都会触发.",[]],["84","Unburden","轻装","消耗掉携带的物品后,速度加倍直到下场.\n当消耗或失去携带的物品时,该宝可梦的基础速度能力值变为2倍.当替换下场、获得新物品或失去此特性时,速度加成消失.",[]],["85","Heatproof","耐热","受到的火属性招式伤害减半.不会受到灼伤伤害.\n受到的火属性招式伤害减半.免疫灼伤伤害以及灼伤状态带来的攻击力降低效果.",["减伤·火"]],["86","Simple","单纯","该宝可梦的能力变化效果翻倍.",[]],["87","Dry Skin","干燥皮肤","水/雨天会回复.火/晴天会受伤.\n受到水属性招式攻击时回复25%的HP,下雨天气时每回合回复12.5%的HP.受到火属性招式伤害增加25%,大晴天天气时每回合损失12.5%的HP.",["免疫·水","雨天免疫位"]],["88","Download","下载","根据对手的防御和特防,提升自身的攻击或特攻1级.\n替换上场时,如果对手的防御高于特防,则自身的特攻提升1级.如果对手的特防高于或等于防御则自身的攻击提升1级.",[]],["89","Iron Fist","铁拳","拳类招式的威力提升至1.3倍.\n拳类招式的威力提升30%.",[]],["90","Poison Heal","毒疗","处于中毒状态时,每回合结束回复1/8的最大HP.\n处于中毒状态时,每回合回复1/8的最大HP,而非受到伤害.对普通中毒和剧毒状态均有效.同时免疫剧毒地形的伤害.",[]],["91","Adaptability","适应力","本系加成从1.5倍提升至2倍.\n使用与自身属性相同的招式时,伤害加成从1.5倍提升至2.0倍.",[]],["92","Skill Link","连续攻击","连续攻击招式总会打出最大次数.\n使连续攻击招式必定打出5次.对于仅能攻击3次或使用大扫荡时,所有攻击进行一次命中判定,而非每次攻击单独判定.",[]],["93","Hydration","湿润之躯","下雨天气时,每回合结束时治愈自身异常状态.\n下雨天气时,每回合结束时治愈所有异常状态",[]],["94","Solar Power","太阳之力","大晴天时,自身最高的攻击能力提升至1.5倍.\n大晴天时,该宝可梦最高的攻击能力值提升50%.",["天气受益·晴天"]],["95","Quick Feet","飞毛腿","处于异常状态时,速度提升至1.5倍.\n处于任何异常状态时,速度能力值提升50%.并且无视麻痹状态带来的速度降低效果.",[]],["96","Normalize","一般皮肤","自身的招式变为一般属性,获得1.1倍威力提升,并无视抗性.\n将所有攻击招式转变为一般属性,并给予10%的威力加成.一般属性招式可以无视属性抗性但无法无视属性免疫.",["转换位·一般（源一般）"]],["97","Sniper","狙击手","击中要害时的伤害倍率从1.5倍提升至2.25倍.\n击中要害时的伤害倍率从1.5倍提升至2.25倍,即额外增加50%的伤害加成.",[]],["98","Magic Guard","魔法防守","仅受攻击伤害.\n免疫所有非攻击性的伤害来源,包括入场陷阱、天气伤害、异常状态以及反伤伤害.",["免疫·非攻击伤害"]],["99","No Guard","无防守","该宝可梦使用或受到的招式必定命中.\n确保该宝可梦使用的所有招式以及所有对该宝可梦使用的招式必定命中.",[]],["100","Stall","慢出","该精灵未出手前受到伤害-30%",[]],["101","Technician","技术高手","威力小于等于60的招式威力提升至1.5倍.\n威力小于等于60的招式威力提升1.5倍.对于基础威力可能超过60的招式（如复仇或毒击）,即使当前威力小于等于60,也不会获得提升.",[]],["102","Leaf Guard","叶子防守","大晴天时,每回合结束时治愈自身异常状态.\n大晴天时,每回合结束时治愈所有异常状态",[]],["103","Klutz","笨拙","自身携带的物品无效.超级石不受影响.\n使所有携带物品的效果失效.物品仍可以被打落或偷走,但不会提供任何增益.投掷等依赖物品的招式会失败.超级石不受此限制.",[]],["104","Mold Breaker","破格","招式可穿透特性生效.同样影响先天特性.\n允许招式无视目标的特性和先天特性,包括那些会干扰效果或降低伤害的特性.无法绕过那些会修改基础能力值的特性,如草之皮毛.",[]],["105","Super Luck","超幸运","自身招式的击中要害率提升1级.\n该宝可梦所有攻击招式的击中要害率提升1级.",[]],["106","Aftermath","引爆","濒死时,使用威力100的大爆炸或迸裂拳.\n当该宝可梦被击倒时,使用威力100的大爆炸或迸裂拳（取两者中威力更高者）.使用爆炸类招式时,必定使目标畏缩.",[]],["107","Anticipation","危险预知","预感到效果绝佳的招式.能闪避一次效果绝佳的招式攻击.\n替换上场时,若对手拥有对自身效果绝佳的招式,则会收到警告.闪避战斗中受到的第一次效果绝佳的招式攻击.",[]],["108","Forewarn","预知梦","出场时,对对手施放威力80的预知未来.\n替换上场时,对目标对手施放一个威力80的预知未来.2回合后攻击,可穿透替身和其他保护效果.一旦施放必定命中,无视命中判定.无法对同一目标施放两次.",[]],["109","Unaware","纯朴","无视对手的能力变化,无论是提升还是降低.\n进行伤害计算时,完全无视对手的所有能力等级变化.",["反强化·纯朴"]],["110","Tinted Lens","有色眼镜","攻击被抵抗时,造成双倍伤害.\n攻击被抵抗时,伤害加倍.如果招式被抵抗（伤害减半或更低）,则最终伤害乘以2倍.",[]],["111","Filter","过滤","受到效果绝佳的招式攻击时,伤害降低35%.\n受到效果绝佳的招式攻击时,伤害降低35%.与其他减伤效果乘法叠加.",[]],["112","Slow Start","慢启动","出场后的前5回合,攻击、特攻和速度减半.\n替换上场后的前5回合,攻击、特攻和速度能力值减半.每次替换下场后,回合计数会重置.",[]],["113","Scrappy","胆量","一般/格斗系招式可以命中幽灵系.免疫威吓和惊吓.\n该宝可梦使用的一般和格斗属性招式能够以普通效果击中幽灵属性宝可梦.免疫威吓和惊吓.",[]],["114","Storm Drain","引水","吸引水属性招式.并提升自身最高的攻击能力.\n该宝可梦会吸引水属性招式,并对其免疫.此外,受到水属性招式攻击后,自身最高的攻击能力提升1级.",["免疫·水","雨天免疫位"]],["115","Ice Body","冰冻之躯","冰雹天气时,每回合回复1/8的最大HP.\n冰雹天气时,每回合结束时回复1/8的最大HP.同时免疫冰雹伤害.",[]],["116","Solid Rock","坚硬岩石","受到效果绝佳的招式攻击时,伤害降低35%.\n受到效果绝佳的招式攻击时,伤害降低35%.与其他减伤效果乘法叠加.",[]],["117","Snow Warning","降雪","出场时引发冰雹,持续8回合.\n出场时引发冰雹,持续8回合（携带冰冷岩石时为12回合）.每回合对非冰属性宝可梦造成1/16的HP伤害.冰属性宝可梦的防御提升50%.使与大晴天相关的招式效果减半.",["天气手·雪"]],["118","Honey Gather","采蜜","每回合有50%几率获得甜甜蜜.\n如果未携带物品,每回合有50%的几率获得甜甜蜜.甜甜蜜每回合可回复1/16的HP,并可在危急时食用以回复1/4的HP.即使该宝可梦最初未携带甜甜蜜作为物品,此效果也有效.",[]],["119","Frisk","察觉","查看对手的物品,并使其物品失效2回合.\n进入战斗时,揭示对手的物品,并使其效果失效2回合.此效果不会阻止超级石及其他类似物品的运作.",[]],["120","Reckless","舍身","会造成反伤伤害的招式威力提升至1.2倍.\n会造成反伤伤害的招式威力提升20%.此加成也适用于通过其他方式（如疯狂状态或特性）获得反伤效果的招式.",[]],["121","Multitype","多属性","自己的属性会根据持有的石板或Z纯晶的属性而改变。",[]],["122","Flower Gift","花之礼","在大晴天时,使己方全队的特攻和特防提升至1.5倍.\n在大晴天时,该宝可梦及其所有同伴的基础特攻和特防提升50%.",[]],["123","Bad Dreams","梦魇","处于睡眠状态的对手每回合结束时损失1/4的最大HP.\n所有处于睡眠状态的对手每回合结束时损失25%的最大HP.",[]],["124","Pickpocket","顺手牵羊","通过接触招式偷走对手携带的物品.\n如果该宝可梦当前未携带物品,通过接触招式攻击时,会偷走目标携带的物品.对超级石及其他类似物品无效.",[]],["125","Sheer Force","强行","以牺牲招式的追加效果为代价,换取1.3倍的威力提升.\n在攻击命中后,移除大部分有益的追加效果,以获得1.3倍的威力提升.使用此类招式时,显著特点是不会受到生命宝珠的反伤.可被移除的效果包括：降低目标能力、提升自身能力、施加异常状态以及造成畏缩.",[]],["126","Contrary","唱反调","对该宝可梦的能力提升会变成降低,反之亦然.\n反转影响该宝可梦的所有能力变化.对自身引起的能力变化同样有效.",[]],["127","Unnerve","紧张感","对手无法使用消耗性物品.\n阻止所有对手宝可梦消耗其携带的物品.",[]],["128","Defiant","不服输","能力被对手降低时,攻击提升2级.\n当该宝可梦的能力被其他宝可梦降低时,其攻击能力提升2级.",[]],["129","Defeatist","软弱","HP1/3以下时，会变得软弱，攻击和特攻会减半。",[]],["130","Cursed Body","诅咒之躯","受到接触招式攻击时,有30%几率使对手的招式陷入封印状态.\n该宝可梦受到接触招式攻击时,有30%的几率使攻击者的该招式陷入封印状态,持续4回合.被封印的招式在效果结束前无法被选择.",[]],["131","Healer","治愈之心","每回合结束时,有30%几率治愈自身或同伴的异常状态.\n在双打对战中,每回合结束时,有30%的几率治愈自身和场上同伴的异常状态.对两只宝可梦分别进行几率判定.",[]],["132","Friend Guard","友情防守","在双打对战中,同伴受到的伤害降低50%.\n在双打对战中,该宝可梦的同伴受到伤害降低50%.与其他减伤来源乘法叠加.",[]],["133","Weak Armor","碎裂铠甲","受到接触招式攻击时：防御降低1级,速度提升2级.\n受到接触招式攻击时,该宝可梦的速度提升2级,防御降低1级.对于连续攻击招式,每次命中都会触发.",[]],["134","Heavy Metal","重金属","受到的幽灵和恶属性伤害减半.\n受到的幽灵和恶属性招式伤害减半.该宝可梦的重量加倍,影响部分招式.",["减伤·幽灵","减伤·恶"]],["135","Light Metal","轻金属","速度提升1.3倍,且该宝可梦的重量减半.\n轻金属使该宝可梦的重量减半,并且速度能力值提升30%.这使得基于重量的招式（如踢倒）对该宝可梦造成的伤害降低.但同时也会降低该宝可梦使用重磅冲撞等基于重量的招式造成的伤害.",[]],["136","Multiscale","多重鳞片","HP全满时,受到的招式伤害减半.\n当该宝可梦HP全满时,受到的所有伤害降低50%.与其他减伤效果乘法叠加.",["减伤·满血"]],["137","Toxic Boost","中毒激升","处于中毒状态时,攻击提升至1.5倍.免疫中毒状态造成的伤害.\n处于中毒状态（普通中毒或剧毒）时,该宝可梦的攻击能力值提升50%.在剧毒地形上,无论是否扎根,都会立刻让自己陷入中毒状态.无视中毒伤害.",[]],["138","Flare Boost","受热激升","处于灼伤状态时,特攻提升至1.5倍.在雾中会点燃自身.\n处于灼伤状态时,该宝可梦的特攻能力值提升50%.无视灼伤伤害.在雾天时立刻让自己陷入灼伤状态.",[]],["139","Harvest","收获","每回合有50%几率回收已使用的树果,大晴天时100%回收.\n每回合结束时,有50%几率回收已使用的树果大晴天时100%回收.包括用于投掷、自然恩惠或被吃掉的树果.",[]],["140","Telepathy","心灵感应","保护己方队伍免受友方伤害.\n在双打对战中,保护该宝可梦免受其同伴使用的所有造成伤害的招式的影响.",[]],["141","Moody","心情不定","每回合随机一项能力大幅提升,另一项能力降低.\n每回合结束时,随机选择一项能力提升2级,并随机选择另一项不同的能力降低1级.",[]],["142","Overcoat","防尘","免疫天气伤害和粉末类招式.受到的特殊伤害降低20%.\n免疫沙暴和冰雹的天气伤害,并阻挡所有粉末类招式,包括催眠粉、麻痹粉、毒粉、蘑菇孢子、棉孢子、愤怒粉、粉末和魔法粉.同时,受到的特殊伤害降低20%.与其他减伤来源乘法叠加.",[]],["143","Poison Touch","毒手","接触时30%让对手变为中毒状态，受到接触攻击时也生效",[]],["144","Regenerator","再生力","替换下场时,回复1/3的最大HP.\n替换下场时,回复33%的最大HP.此回复效果不受回复封锁影响.",["轮转·再生"]],["145","Big Pecks","健壮胸肌","接触类招式的威力提升至1.3倍.\n接触类招式的威力提升30%.",[]],["146","Sand Rush","拨沙","沙暴天气时，速度1.5倍",["沙暴速度位（×1.5）"]],["147","Wonder Skin","奇迹皮肤","阻挡大多数伤害增益和连续攻击特性.\n免疫对手所有提升伤害的特性效果,亲子爱和多头龙特性除外.",[]],["148","Analytic","分析","如果在目标之后行动,招式威力提升至1.3倍.\n当该宝可梦在目标之后行动时,攻击威力提升30%.",[]],["149","Illusion","幻觉","伪装成队伍中最后的宝可梦,在受到攻击前威力提升1.3倍.\n使该宝可梦伪装成队伍中最后存活的同伴.在幻觉被打破前,该宝可梦造成的伤害提升30%.",[]],["150","Imposter","变身者","出场时,变身为对手.\n替换上场时,该宝可梦变身为对手.复制其外形、能力值（HP除外）、属性、特性、招式以及能力变化.每个被复制的招式拥有5点PP如果目标有替身、已经变身、处于幻觉状态或处于部分无敌状态,则无法变身.",[]],["151","Infiltrator","穿透","自身的招式可以穿透替身和伤害减免屏障.\n允许招式穿透光墙、反射壁、神秘守护、白雾和替身的效果.",[]],["152","Mummy","木乃伊","受到接触攻击时,使攻击者的特性变为木乃伊.\n当该宝可梦受到其他宝可梦的接触招式攻击时,如果对方不具有此特性,则对方的当前特性会被替换为木乃伊.",[]],["153","Moxie","自信过度","击倒对手时,攻击提升1级.\n每当该宝可梦通过直接攻击击倒对手时,其攻击能力值提升1级.",[]],["154","Justified","正义之心","免疫恶属性招式,受到恶属性招式攻击时,提升攻击能力.\n免疫恶属性招式,并在受到恶属性招式攻击时,攻击能力值提升1级.",["免疫·恶"]],["155","Rattled","胆怯","受到恶、幽灵或虫属性的招式攻击或是畏缩时速度会提高",[]],["156","Magic Bounce","魔法镜","将变化招式弹回给使用者.\n在大部分变化招式生效前,将其反弹回原使用者.被反弹的招式无需额外命中判定直接作用于原使用者.无法反弹已被反弹的招式.",[]],["157","Sap Sipper","食草","吸收草属性招式,提升自身最高的攻击能力.\n免疫草属性招式,并在受到草属性招式攻击时,自身最高的攻击能力值提升1级.",["免疫·草"]],["158","Prankster","恶作剧之心","变化招式拥有+1优先度,但对恶属性对手失效.\n变化类招式获得+1优先度.当直接以恶属性宝可梦为目标时变化招式会失败.",["先制变化招"]],["159","Sand Force","沙之力","在沙暴中,自身最高的攻击能力提升至1.5倍.\n在沙暴中,该宝可梦最高的攻击能力值提升50%.免疫沙暴伤害.",["天气受益·沙暴"]],["160","Iron Barbs","铁刺","用铁刺给予接触到自己的对手最大HP的1/8伤害",[]],["161","Zen Mode","达摩模式","入场时变为达摩模式",[]],["162","Victory Star","胜利之星","为己方和同伴的招式提供1.2倍命中率提升.\n在双打对战中,该宝可梦及其同伴的招式命中率提升1.2倍.",[]],["163","Turboblaze","涡轮火焰","招式可穿透特性.为自身添加火属性.\n允许招式无视目标的特性和先天特性,包括那些会干扰效果或降低伤害的特性.无法绕过会修改基础能力值的特性,如草之皮毛.为自身添加火属性.即使失去此特性,添加的火属性在替换下场前依然保留.",[]],["164","Teravolt","兆级电压","招式可穿透特性.为自身添加电属性.\n允许招式无视目标的特性和先天特性,包括那些会干扰效果或降低伤害的特性.无法绕过会修改基础能力值的特性,如草之皮毛.为自身添加电属性.即使失去此特性,添加的电属性在替换下场前依然保留.",[]],["165","Aroma Veil","芳香幕","保护己方队伍免受着迷、回复封锁和封印效果.\n保护该宝可梦及其同伴免受着迷、回复封锁效果以及封印类招式（包括封印、挑衅、再来一次和无理取闹）的影响.",[]],["166","Flower Veil","花幕","保护草属性的同伴免受异常状态和能力降低.\n防止草属性同伴陷入任何异常状态或能力降低.包括自身引起的能力降低.",[]],["167","Cheek Pouch","颊囊","此特性无效果.\n无效果.",[]],["168","Protean","变幻自如","根据即将使用的招式改变自身属性.\n每次攻击前,该宝可梦的属性会变为与所用招式相同的属性.每回合触发一次.",[]],["169","Fur Coat","毛皮大衣","受到的物理招式伤害减半.不会加倍防御.\n所有受到的物理攻击伤害减半.与其他减伤来源乘法叠加.",[]],["170","Magician","魔术师","使用非接触类招式后,偷走对手携带的物品.\n如果该宝可梦当前未携带物品,使用非接触类招式命中后,会偷走目标携带的物品.对超级石及其他类似物品无效.",[]],["171","Bulletproof","防弹","免疫基于投射物、球或炸弹的招式.\n免疫球、炸弹和投射物类招式.包括酸液炸弹、岩石炮、花粉团和投球.",[]],["172","Competitive","好胜","能力被对手降低时,特攻提升2级.\n当该宝可梦的能力被其他宝可梦降低时,其特攻能力提升2级.",[]],["173","Strong Jaw","强壮之颚","啃咬类招式威力提升至1.3倍.\n啃咬和颚类招式的威力提升30%.",[]],["174","Refrigerate","冰冻皮肤","一般属性招式变为冰属性.冰属性招式得到强化.\n将该宝可梦的一般属性招式变为冰属性.如果该宝可梦是冰属性,其冰属性招式有10%的几率造成冻伤；否则,它获得冰属性的本系加成.",["转换位·冰（源一般）"]],["175","Sweet Veil","甜幕","该宝可梦及其同伴免疫睡眠.\n在双打对战中,为该宝可梦及其同伴提供睡眠免疫.",[]],["176","Stance Change","战斗切换","根据使用的招式在刀剑形态和盾牌形态之间切换.\n根据使用的招式改变坚盾剑怪的形态.盾牌形态在使用攻击招式时切换为刀剑形态.刀剑形态在使用王者盾牌时切换为盾牌形态.终极形态根据招式类型在物理/特殊之间切换.此特性无法被压制.形态变化在招式执行前发生.",[]],["177","Gale Wings","疾风之翼","HP全满时,飞行属性招式获得+1优先度.\n当HP全满时,赋予飞行属性招式+1优先度.",[]],["178","Mega Launcher","超级发射器","波动、波导、脉冲类招式威力提升至1.3倍.\n脉冲、波导、波动和光环类招式威力提升30%.",[]],["179","Grass Pelt","草之毛皮","在青草场地时，防御1.5倍",["场地受益·青草场地"]],["180","Symbiosis","共生","当同伴消耗其携带物品时,将自己的物品传递给同伴.\n在同伴消耗或使用掉其携带的物品后,立即将持有者的物品传递给该同伴.",[]],["181","Tough Claws","硬爪","接触类招式的威力提升至1.3倍.\n接触类招式的威力提升30%.",[]],["182","Pixilate","妖精皮肤","一般属性招式变为妖精属性.妖精属性招式得到强化.\n将该宝可梦的一般属性招式变为妖精属性.如果该宝可梦是妖精属性,其妖精属性招式有10%的几率造成着迷；否则,它获得妖精属性的本系加成.",["转换位·妖精（源一般）"]],["183","Gooey","黏滑","与该宝可梦发生接触的敌人,其速度降低.\n当该宝可梦受到接触招式攻击时,攻击者的速度降低1级.对于连续攻击招式,每次命中都会触发.",[]],["184","Aerilate","飞行皮肤","一般属性招式变为飞行属性.飞行属性招式得到强化.\n将该宝可梦的一般属性招式变为飞行属性.如果该宝可梦是飞行属性,其飞行属性招式的速度提升10%；否则,它获得飞行属性的本系加成.",["转换位·飞行（源一般）"]],["185","Parental Bond","亲子爱","招式攻击两次.第一击威力100%,第二击威力25%.\n使所有攻击连续命中两次.第一击造成100%伤害,第二击造成25%伤害.每次攻击独立判定追加效果（畏缩除外）.可穿透坚壁/奇迹皮肤.",[]],["186","Dark Aura","暗黑气场","在该宝可梦在场时,所有宝可梦的恶属性招式威力提升至1.33倍.\n使用者、其同伴以及对手的所有恶属性招式获得1.33倍的威力提升.此加成会被气场破坏反转.",[]],["187","Fairy Aura","妖精气场","在该宝可梦在场时,所有宝可梦的妖精属性招式威力提升至1.33倍.\n使用者、其同伴以及对手的所有妖精属性招式获得1.33倍的威力提升.此加成会被气场破坏反转.",[]],["188","Aura Break","气场破坏","取消气场特性,并使其效果变为降低25%的威力.\n使暗黑气场和妖精气场的效果反转,将其对应属性的招式威力降低25%,而非提升33%.",[]],["189","Primordial Sea","始源之海","制造终焉大雨,持续到下场.火属性招式无法使用.\n创造终焉大雨,持续到使用者下场.完全无效所有造成伤害的火属性招式.水属性招式获得50%威力提升除其他原始天气外,无法被覆盖.激活与雨天相关招式的额外效果使与大晴天相关的招式效果减半.",[]],["190","Desolate Land","终结之地","制造终焉大晴天,持续到下场.水属性招式无法使用.\n创造终焉大晴天,持续到使用者下场.完全无效所有造成伤害的水属性招式.火属性招式获得50%威力提升除其他原始天气外,无法被覆盖.激活与大晴天相关招式的额外效果.",[]],["191","Delta Stream","德尔塔气流","制造强风,持续到下场.基于天气的招式无法使用.\n创造强风,持续到使用者下场.将场上所有飞行属性宝可梦受到的效果绝佳伤害变为普通伤害.阻止所有基于天气的招式命中对手.除其他原始天气外,无法被覆盖.",[]],["192","Stamina","持久力","受到攻击时,防御提升1级.受到击中要害的攻击时提升至最大.\n受到攻击时,该宝可梦的防御提升1级；若受到击中要害的攻击,则防御能力值提升至最大.对于连续攻击招式,每次命中都会触发.",[]],["193","Wimp Out","跃跃欲逃","当HP首次降至1/2或以下时,立即替换下场.\n当该宝可梦受到伤害,且HP在战斗中首次降至50%或以下时,它会替换下场以保安全.对于连续攻击招式,在最后一击后触发.",[]],["194","Emergency Exit","危险回避","HP变为一半时，为了回避危险，会退回到同行队伍中。",[]],["195","Water Compaction","遇水凝固","受到的水属性招式伤害减半.被水属性招式击中后,防御提升2级.\n受到的水属性招式伤害降低50%,并且被水属性招式击中后,防御提升2级.与其他减伤来源乘法叠加.防御提升效果在攻击命中后生效对于连续攻击招式,每次命中都会触发.",[]],["196","Merciless","不仁不义","攻击处于减速、中毒、麻痹或流血状态的对手时,必定会心一击.\n对处于中毒、麻痹、流血或速度降低状态的目标,必定造成击中要害.",[]],["197","Shields Down","界限盾壳","当HP降至1/2或以下时,变身为核心形态.\n当小陨星的HP降至50%或以下时,从流星形态变身为核心形态.在流星形态下,免疫所有异常状态.使用破壳时,无论当前HP多少,立即变身为核心形态.在战斗中一旦变身,无法恢复为流星形态.",[]],["198","Stakeout","蹲守","对刚替换上场的对手造成双倍伤害.\n对刚替换上场的对手造成双倍伤害.仅在对手替换上场后的第一回合内生效.",[]],["199","Water Bubble","水泡","受到的火属性伤害减半.造成的水属性伤害加倍.不会灼伤.\n水属性招式威力加倍,受到的火属性伤害降低50%.同时完全免疫灼伤,并在获得此特性时移除已有的灼伤状态.",["减伤·火","输出位·水"]],["200","Steelworker","钢能力者","钢属性的招式威力1.3倍",[]],["201","Berserk","怒火冲天","当HP降至1/2或以下时,自身最高的攻击能力提升1级.\n当该宝可梦因对手的攻击而使HP降至一半或以下时,其最高的攻击能力值提升1级.根据能力等级决定提升哪一项.每场战斗仅触发一次.其他伤害来源使HP降至一半或以下不会触发此特性.",[]],["202","Slush Rush","拨雪","在冰雹中,该宝可梦的速度提升至1.5倍.\n在冰雹中,该宝可梦的速度能力值提升50%.同时免疫冰雹伤害.",["雪天速度位（×1.5）"]],["203","Long Reach","远隔","物理招式获得1.2倍威力加成,且不会接触.\n远隔特性防止该宝可梦在使用接触类招式时与目标发生接触.此外,物理招式获得1.2倍的伤害加成.",[]],["204","Liquid Voice","湿润之声","声音类招式获得1.2倍威力加成,若为一般属性则变为水属性.\n湿润之声将一般属性的声音类招式转变为水属性,并将其威力提升20%.",[]],["205","Triage","先行治疗","可以率先使出回复招式，先制度+3",[]],["206","Galvanize","电气皮肤","一般属性招式变为电属性.电属性招式得到强化.\n将该宝可梦的一般属性招式变为电属性.如果该宝可梦是电属性,其电属性招式有10%的几率造成麻痹；否则,它获得电属性的本系加成.",["转换位·电（源一般）"]],["207","Surge Surfer","冲浪之尾","在电气场地中,速度提升至1.5倍.\n在电气场地生效时,该宝可梦的速度能力值提升50%.场地开始时立即生效,场地结束时加成消失.",[]],["208","Schooling","鱼群","等级20或以上时：变为鱼群形态,直到HP降至1/4或以下.\n当等级达到20或以上时,变身为鱼群形态.当HP降至25%或以下时,恢复为单独形态.此形态变化在出场时和每回合结束时自动触发.无法以任何方式覆盖、压制、交换或复制.",[]],["209","Disguise","画皮","抵挡一次攻击.在雾中可恢复此保护效果.\n画皮会抵挡第一个命中该宝可梦的造成伤害的招式,之后改变形态.仅能抵挡非变化招式.在雾中,每次替换上场或当雾重新出现时,画皮会立即恢复.",[]],["210","Battle Bond","牵绊变身","击倒对手后,变身为牵绊形态.\n当该宝可梦给予对手最后一击使其濒死时,立即触发形态变化.无法被复制.",[]],["211","Power Construct","群聚变形","当HP降至1/2或以下时,变身为完全体形态.\n群聚变形会在任何回合结束时,如果基格尔德50%或10%形态的HP降至50%或以下,则使其变身为完全体形态.完全体形态拥有高达216的HP（从108翻倍）,使其成为极其耐打的坦克.此形态变化在战斗中永久持续,且无法被压制.",[]],["212","Corrosion","腐蚀","毒属性招式对钢属性效果绝佳.可使任何属性的宝可梦中毒.\n毒属性招式对钢属性宝可梦变得效果绝佳.此外,该宝可梦可以使任何属性的宝可梦陷入中毒状态.",[]],["213","Comatose","绝对睡眠","可以行动,但始终处于睡眠状态.免疫异常状态.\n绝对睡眠特性使该宝可梦在招式和状态判定中被视为处于睡眠状态.该宝可梦可以正常行动,并且免疫所有异常状态.此特性无法被复制或压制.使用招式睡觉会失败.",[]],["214","Queenly Majesty","女王的威严","对方无法对我方使出先制招式",[]],["215","Innards Out","飞出的内在物","被对手打倒的时候，会给予对手相当于HP剩余量的伤害。",[]],["216","Dancer","舞者","模仿其他宝可梦使用的舞蹈招式.\n当场上任何宝可梦使用舞蹈类招式后,该宝可梦会立即使用相同的招式每回合对每个招式触发一次.",[]],["217","Battery","蓄电池","使同伴的特殊攻击威力提升至1.3倍.\n在双打对战中,蓄电池为同伴宝可梦的特殊攻击提供30%的威力提升.不影响使用者自身的招式.",[]],["218","Fluffy","毛茸茸","受到的接触类招式伤害减半,但火属性招式会造成2倍伤害.\n毛茸茸使受到的接触类招式伤害降低50%.火属性招式对该宝可梦造成双倍伤害.与其他减伤效果乘法叠加.",[]],["219","Dazzling","鲜艳之躯","使对方无法对我方使出先制招式",[]],["220","Soul-Heart","魂心","场上任何宝可梦被击倒时,特攻提升1级.\n当战场上任何宝可梦（包括同伴和对手）濒死时,魂心特性会提升该宝可梦的特攻1级.",[]],["221","Tangling Hair","卷发","与该宝可梦发生接触的敌人,其速度降低.\n当该宝可梦受到接触招式攻击时,攻击者的速度降低1级.对于连续攻击招式,每次命中都会触发.",[]],["222","Receiver","接球手","在双打对战中,复制濒死同伴的特性.\n接球手会复制濒死同伴的特性,替换自身的接球手特性.此效果持续到替换下场.",[]],["223","Power of Alchemy","化学之力","出场时转化树果.物品失去时转化物品.\n出场时,将所有对手的树果转化为黑色污泥.战斗中任何宝可梦失去物品时,该物品会被黑色污泥取代.如果黑色污泥被移除,则会被大金珠取代.",[]],["224","Beast Boost","异兽提升","击倒对手后,自身最高的计算后能力值提升1级.\n每当该宝可梦击倒一名对手时,其最高的计算后能力值提升1级被提升的能力基于不考虑当前能力等级变化的原始能力值决定.",[]],["225","RKS System","AR系统","携带的记忆碟决定其属性.同时拥有变幻自在和适应力特性.\nAR系统根据携带的记忆碟改变使用者的形态.每次攻击前,使用者的属性会变为与所用招式相同的属性.本系加成从1.5倍提升至2.0倍.",[]],["226","Electro Surge","电气制造者","出场时制造电气场地,持续8回合.\n出场时制造电气场地,持续8回合（携带场地制造机时为12回合）.地面上的宝可梦不会陷入睡眠,且电属性招式威力提升30%.激活时覆盖其他场地.",["场手·电场"]],["227","Psychic Surge","精神制造者","出场时制造精神场地,持续8回合.\n出场时制造精神场地,持续8回合（携带场地制造机时为12回合）.地面上的宝可梦免疫对手的先制招式.超能力属性招式威力提升30%.广阔战场可以攻击所有对手且威力提升.自然之力变为精神强念.覆盖其他现有场地.",["场手·精神场地"]],["228","Misty Surge","薄雾制造者","出场时制造薄雾场地,持续8回合.\n出场时制造薄雾场地,持续8回合（携带场地制造机时为12回合）.薄雾场地防止地面上的宝可梦陷入任何异常状态,并使妖精属性招式威力提升30%.覆盖现有场地.",["场手·薄雾场地"]],["229","Grassy Surge","青草制造者","出场时制造青草场地,持续8回合.\n出场时制造青草场地,持续8回合（携带场地制造机时为12回合）地面上的宝可梦每回合回复1/16的HP,且草属性招式威力提升30%.覆盖其他场地.",["场手·青草场地"]],["230","Full Metal Body","金属防护","免疫能力降低.\n金属防护使该宝可梦免疫所有来自招式或特性的能力降低效果.包括因使用过热等招式导致的自身能力降低.",[]],["231","Shadow Shield","幻影防守","HP全满时,受到的招式伤害减半.\n当HP全满时,幻影防守使受到的所有攻击伤害减半.与其他减伤来源乘法叠加.",["减伤·满血"]],["232","Prism Armor","棱镜装甲","受到效果绝佳的招式攻击时,伤害降低35%.\n受到效果绝佳的招式攻击时,伤害降低35%.与其他减伤效果乘法叠加.",[]],["233","Neuroforce","脑核之力","对效果绝佳的招式提供额外的1.35倍威力加成.\n效果绝佳的攻击威力提升35%.",[]],["234","Intrepid Sword","不挠之剑","出场时,攻击提升1级.\n不挠之剑在替换上场时,使该宝可梦的攻击能力提升1级.",[]],["235","Dauntless Shield","不屈之盾","出场时,防御提升1级.\n不屈之盾在进入战斗时,立即将防御能力提升1级.",[]],["236","Libero","自由者","使用招式前,将自身属性变为与招式相同的属性.\n自由者在攻击前,会将使用者的属性覆盖为与所用招式相同的属性.挣扎招式无法触发此效果.",[]],["237","Ball Fetch","捡球","对战内无效",[]],["238","Cotton Down","棉絮","受到攻击时,降低所有对手的速度1级.\n棉絮特性在该宝可梦受到任何攻击时触发,降低所有宝可梦的速度1级.对于连续攻击招式,每次命中都会触发.",[]],["239","Propeller Tail","螺旋尾鳍","悠游自如 + 免疫招式吸引.\n螺旋尾鳍使该宝可梦在雨天时速度提升50%,并且免疫招式吸引效果.速度加成在所有形式的雨天中都有效.",[]],["240","Mirror Armor","镜甲","将敌人施加的任何能力降低效果反弹回去.\n镜甲将所有以该宝可梦为目标的降低能力效果反弹给攻击者.反弹效果无视免疫.",[]],["241","Gulp Missile","一口导弹","使用潜水/冲浪后叼住猎物.受到攻击时,向敌人射出猎物.\n当古月鸟使用冲浪、三重潜水或潜水时,它会叼住猎物：HP小于50%时为叼喙形态,HP大于50%时为吞喙形态.在任一形态下受到攻击时,会向攻击者吐出猎物,造成其最大HP25%的伤害,并返回普通形态.叼喙形态还会降低防御1级；吞喙形态会麻痹目标.此特性无法被压制等.",[]],["242","Stalwart","坚毅","不受招式吸引、击中要害或特性压制的影响.\n招式不会被吸引,不会受到击中要害,且特性不会被压制.特性压制包括破格、化学变化气体和菌丝之力等效果.",[]],["243","Steam Engine","蒸汽机","受到火属性或水属性招式攻击时,速度提升至最大.\n受到任何火属性或水属性招式攻击后,蒸汽机特性立即将速度能力值提升至+6级.提升效果在受到伤害后生效.",[]],["244","Punk Rock","庞克摇滚","声音类招式造成1.3倍伤害.受到的声音类招式伤害降低50%.\n庞克摇滚使该宝可梦的声音类招式威力提升30%,并且受到的声音类招式伤害降低50%.伤害减免与其他来源乘法叠加.",[]],["245","Sand Spit","吐沙","受到攻击时，会刮起沙暴，持续8回合",[]],["246","Ice Scales","冰鳞粉","受到的特殊招式伤害减半.不会加倍特防.\n所有受到的特殊攻击伤害减半.与其他减伤来源乘法叠加.",["减伤·特殊"]],["247","Ripen","熟成","树果提供的抗性、回复和能力提升效果加倍.\n熟成使所有树果的有益效果加倍回复类树果回复量加倍,提升能力的树果改为提升2级,抵抗树果将效果绝佳的伤害降低75%而非50%,回复PP的树果回复量加倍.",[]],["248","Ice Face","结冻头","抵挡一次攻击.在冰雹中可恢复此保护效果.\n结冻头使哭哭面具在受到物理攻击后变身为无头形态,并抵消一次伤害.在无头形态下,如果场上出现冰雹或该宝可梦被替换上场,则恢复为结冻头形态.无法被复制或压制.",[]],["249","Power Spot","能量点","使同伴的攻击威力提升至1.3倍.\n在双打对战中,能量点使同伴的攻击威力提升30%.使用者自身不受此加成影响.",[]],["250","Mimicry","拟态","根据当前场地改变自身属性.\n拟态使该宝可梦的属性变为与当前场地一致：电气场地变为电属性,薄雾场地变为妖精属性,青草场地变为草属性,精神场地变为超能力属性.属性变化持续到场地结束或该宝可梦下场.保留通过浸水等招式改变的属性.",[]],["251","Screen Cleaner","除障","出场时清除双方场上的屏障.可以重置屏障.\n除障特性在该宝可梦进入战斗时,移除双方场地上所有的防护屏障、反射壁、光墙、极光幕和烟幕它还允许该宝可梦在屏障已激活时重新设置它们,刷新其持续时间.",[]],["252","Steely Spirit","钢之意志","我方的钢属性攻击1.3倍",[]],["253","Perish Body","灭亡之躯","受到攻击时,发动灭亡之歌.\n受到接触招式攻击时,灭亡之躯对使用者和攻击者发动灭亡之歌.除非替换下场,否则两只宝可梦将在3回合后濒死.",[]],["254","WandrngSprit","游魂","受到接触攻击时,与攻击者交换特性.\n受到接触招式攻击时,游魂特性会与攻击者交换特性.两只宝可梦在替换下场后恢复各自原有的特性.无法与同样不能被复制或压制的特性交换.",[]],["255","Gorilla Tactics","一猩一意","自身攻击提升1.5倍,但只能使用最初选择的招式.\n一猩一意使物理招式威力提升50%,但会锁定使用者只能使用首次选择的招式,直到替换下场.",[]],["256","Neutralizing Gas","化学变化气体","所有特性都失效.\n用气体充满战场,完全压制除无法压制外的所有特性.效果在使用者在场时持续.在使用者尝试替换下场后,所有被压制的特性会重新触发其入场效果.无法被复制或交换.",[]],["257","Pastel Veil","粉彩护幕","出场时施放神秘守护.\n粉彩护幕在该宝可梦进入战斗时,自动为其队伍设置神秘守护.神秘守护持续5回合,保护所有队友免受异常状态.",[]],["258","HungerSwitch","饱了又饿","每回合结束后在吃饱形态和饥饿形态之间切换.\n每回合结束时自动在吃饱形态和饥饿形态之间切换.无法以任何方式覆盖、压制、交换或复制.",[]],["259","Quick Draw","速击","30%几率先出手.\n速击有30%的几率让使用者在当前优先度层级内率先行动.与先制之爪的效果乘法叠加,使总触发几率达到44%.",[]],["260","Unseen Fist","无形拳","接触类招式可以穿透保护效果.\n无形拳允许所有接触类招式穿透保护类招式,并忽略与其相关的任何附加效果.",[]],["261","CuriusMedicn","怪药","出场时重置同伴的能力变化.\n怪药在使用者出场时,移除同伴的所有正向和负向能力变化.",[]],["262","Transistor","电晶体","电属性招式威力提升至1.5倍.\n电晶体使所有电属性招式的威力提升50%.与其他伤害加成效果加法叠加.",["输出位·电"]],["263","Dragon's Maw","龙颚","龙属性招式威力提升至1.5倍.\n龙颚使龙属性招式的威力提升50%.",["输出位·龙"]],["264","ChillngNeigh","苍白嘶鸣","击倒对手时,攻击提升1级.\n当该宝可梦通过直接攻击击倒对手时,其攻击能力值提升1级.",[]],["265","Grim Neigh","漆黑嘶鸣","击倒对手时,特攻提升1级.\n漆黑嘶鸣特性在该宝可梦通过直接攻击使对手濒死时,提升其特攻能力值1级.",[]],["266","As One","人马一体","紧张感 + 苍白嘶鸣.\n阻止所有对手宝可梦消耗其携带的物品.当该宝可梦通过直接攻击击倒对手时,其攻击能力值提升1级.",[]],["267","As One","人马一体","紧张感 + 漆黑嘶鸣.\n阻止所有对手宝可梦消耗其携带的物品.当该宝可梦通过直接攻击击倒对手时,其特攻能力值提升1级.",[]],["268","Chloroplast","叶绿体","气象球、日光束/刃、生长视为在大晴天下使用.\n气象球威力加倍并变为火属性.日光类招式无需蓄力.生长使攻击和特攻提升2级.月光、晨光和光合作用回复2/3的最大HP.草之誓约和水之誓约组合分别产生火海或彩虹效果.",[]],["269","Whiteout","冰天雪地","冰雹天气下冰属性招式1.5倍",["天气受益·冰雹"]],["270","Pyromancy","点燃","火属性招式灼伤概率5倍",[]],["271","Keen Edge","锐利之刃","劈砍类招式1.3倍",[]],["272","Prism Scales","棱镜鳞片","受到的特殊攻击伤害降低30%.\n棱镜鳞片使受到的所有特殊攻击伤害降低30%.与其他减伤来源乘法叠加.",[]],["273","Power Fists","力量之拳","拳类招式造成特殊伤害且威力1.3倍",[]],["274","Sand Song","地之歌","一般属性的招式会变为地面属性，威力1.2倍",[]],["275","Rampage","狂暴","充能恢复型招式在打倒单位后无需恢复",[]],["276","Vengeance","猛鬼","幽灵属性招式1.2倍，HP1/3以下1.5倍",["输出位·幽灵"]],["277","Blitz Boxer","闪电拳击","HP满时拳类招式+1优先级",[]],["278","Antarctic Bird","南极鸟","冰属性和飞行属性招式威力提升至1.3倍.\n南极鸟使冰属性和飞行属性招式的威力提升30%.与其他伤害加成效果加法叠加.",[]],["279","Immolate","火焰皮肤","一般属性的招式会变为火属性，威力1.1倍",[]],["280","Crystallize","结晶化","岩石属性招式变为冰属性，威力1.1倍",["转换位·冰（源岩石）"]],["281","Electrocytes","发电细胞","电属性招式1.25倍",[]],["282","Aerodynamics","空气动力","被飞行属性招式攻击上升一段速度",["免疫·飞行"]],["283","Christmas Spirit","雪之精神","冰雹天气下受到伤害减半",[]],["284","Exploit Weakness","弱点开发","攻击处于异常状态下的对手威力1.25倍",[]],["285","Ground Shock","地面冲击","地面系不免疫电属性招式而是改为抵抗",[]],["286","Ancient Idol","古代神像","攻击时使用防御和特殊防御代替攻击特攻进行计算",[]],["287","Mystic Power","奇迹力量","所有属性招式都获得1.5倍属性一致加成",[]],["288","Perfectionist","完美主义","威力<51的招式击中要害率+1，威力<26招式+1优先级",[]],["289","Growing Tooth","增强之牙","使用牙类招式上升一段攻击",[]],["290","Inflatable","充气","受到飞行或火属性招式攻击时,防御和特防各提升1级.\n受到任何火属性或飞行属性招式攻击时,防御和特防能力值各提升1级.对于连续攻击招式,每次命中都会触发.能力提升效果在攻击命中后生效.",[]],["291","Aurora Borealis","北极光","冰属性招式获得本系加成.招式总能享受到冰雹的增益.\n北极光使所有冰属性招式获得本系加成,无论该宝可梦的属性如何.气象球变为冰属性且威力加倍,极光幕无需冰雹即可生效,基于天气的冰属性招式（如暴风雪）必定命中.",[]],["292","Avenger","复仇","如果上轮有友方精灵被打倒，下一个招式1.5倍",[]],["293","Let's Roll","滚起来","入场释放变圆",[]],["294","Aquatic","水生","出场时添加水属性.\n进入战斗时,为使用者的当前属性添加水属性即使失去此特性,添加的水属性在替换下场前依然保留.",[]],["295","Loud Bang","响亮噪声","声音类招式50%概率使对手混乱",[]],["296","Lead Coat","铅质外壳","受到物理伤害减少40%，自生速度*0.9",[]],["297","Amphibious","水栖","水属性招式1.5倍",[]],["298","Grounded","接地","出场时添加地面属性.\n接地特性在出场时为该宝可梦添加地面属性.即使失去此特性,添加的地面属性在替换下场前依然保留.",[]],["299","Earthbound","地基","地面属性招式1.25倍",["输出位·地面"]],["300","Fighting Spirit","格斗皮肤","一般属性的招式会变为格斗属性，威力1.1倍",[]],["301","Cryptic Power","魔力非凡","特殊攻击变为2倍",[]],["302","Coil Up","盘卷待发","入场时给第一个使用的咬类招式一次+1优先度",[]],["303","Fossilized","化石化","受到岩石属性招式减半，自身岩石属性招式1.2倍",["减伤·岩石","输出位·岩石"]],["304","Magical Dust","魔法粉尘","被接触类招式攻击时给予对方超能属性",[]],["305","Dreamcatcher","捕梦网","场上有单位睡眠时招式威力2倍",[]],["306","Nocturnal","黑暗亲和","恶属性招式1.25倍，受到恶/妖精属性伤害-25%",[]],["307","Self Sufficient","自给自足","每回合结束时回复1/16的最大HP.",[]],["308","Tectonize","地面皮肤","一般属性的招式会变为地面属性，威力1.1倍",[]],["309","Ice Age","冰川","自身获得冰属性",[]],["310","Half Drake","半龙化","自身获得龙属性",[]],["311","Liquified","液化","受到的接触类招式伤害减半,但受到的水属性招式会造成2倍伤害.\n液化使受到的接触类招式伤害降低50%,但受到的水属性招式伤害变为2倍.与其他减伤来源乘法叠加.",[]],["312","Dragonfly","飞龙","半龙化+免疫地面招式攻击",["免疫·地面","地面免疫位"]],["313","Dragonslayer","猎龙者","对龙属性精灵伤害1.5倍，受到龙属性招式伤害减半",[]],["314","Mountaineer","登山","免疫岩石类招式和隐形岩的伤害",["免疫·岩石"]],["315","Hydrate","水之皮肤","一般属性的招式会变为水属性，威力1.1倍",["转换位·水（源一般）"]],["316","Metallic","金属化","出场时添加钢属性.\n进入战斗时,为使用者的当前属性添加钢属性即使失去此特性,添加的钢属性在替换下场前依然保留.",[]],["317","Permafrost","永冻层","受到效果绝佳的攻击时，受到伤害减少25%",[]],["318","Primal Armor","根源盔甲","受到效果绝佳的攻击时，受到伤害减少50%",[]],["319","Raging Boxer","暴怒拳手","拳类招式攻击两次第一次威力不变第二次40%",[]],["320","Air Blower","鼓风","入场时使用顺风，持续三回合",[]],["321","Juggernaut","重型坦克","麻痹免疫，使用接触类招式时获得防御力20%加成",[]],["322","Short Circuit","猛电","电属性招式1.2倍，HP1/3以下1.5倍",["输出位·电"]],["323","Majestic Bird","神鸟威严","特殊攻击变为1.5倍",[]],["324","Phantom","幽灵化","自身获得幽灵属性",[]],["325","Intoxicate","剧毒皮肤","一般属性的招式会变为毒属性，威力1.1倍",["转换位·毒（源一般）"]],["326","Impenetrable","顽固","不会受到攻击以外的伤害",["免疫·非攻击伤害"]],["327","Hypnotist","催眠师","该宝可梦使用的催眠术命中率为90%.\n将催眠术的命中率提升至90%.不锁定为90%,该招式仍会受到命中率/闪避率变化的影响.",[]],["328","Overwhelm","压倒","龙属性招式可以击中妖精属性，免疫威吓和恐吓",[]],["329","Scare","恐吓","入场降低对手特攻",[]],["330","Majestic Moth","虫之威严","入场自身能力值最高的一项上升一段",[]],["331","Soul Eater","灵魂食者","自身打倒精灵时回复最大HP的1/4",[]],["332","Soul Linker","灵魂链接","攻击者受到对自身造成的所有伤害,自身攻击时也受影响.\n当使用者受到直接攻击时,对手受到等量伤害.当使用者造成直接攻击伤害时,自身也受到等量伤害.当任意一方濒死、通过痛平分受到伤害或对另一个拥有灵魂链接特性的宝可梦时,此特性不会触发.",[]],["333","Sweet Dreams","美梦","处于睡眠状态时,每回合回复1/8的最大HP.免疫梦魇.\n美梦特性在使用者处于睡眠状态或拥有绝对睡眠特性时,每回合结束时回复1/8的最大HP.此外,它免疫梦魇特性的伤害.",[]],["334","Bad Luck","厄运","对手无法会心一击,命中率降低5%,且无法触发追加效果.\n对手无法造成击中要害,总是造成最低伤害（85%而非85-100%）,无法触发非必定触发的追加效果,并且有5%的几率招式落空.",[]],["335","Haunted Spirit","魂出没","被打到后给予对方诅咒",[]],["336","Electric Burst","电力爆发","电属性招式1.35倍，受到10%反伤",[]],["337","Raw Wood","原木","受到的草属性伤害减半.自身的草属性招式威力提升1.2倍.\n受到的草属性攻击伤害降低50%,同时使用者自身的草属性招式威力提升20%.伤害减免与其他来源乘法叠加.",["减伤·草","输出位·草"]],["338","Solenoglyphs","蛇牙","咬类招式50%概率剧毒对方",[]],["339","Spider Lair","蛛穴","入场时使用黏黏网，持续5回合",[]],["340","Fatal Precision","精准致命","效果绝佳招式必定命中且威力1.2倍",[]],["341","Fort Knox","要塞","防止伤害增幅，以及多头特性",[]],["342","Seaweed","海草","如果自身是草属性,受到的火属性伤害减半.草属性招式对火属性造成2倍伤害.\n如果使用者是草属性,其受到的火属性攻击伤害减半,并且使用草属性招式对火属性宝可梦造成2倍伤害.伤害减免与其他来源乘法叠加.",["减伤·火"]],["343","Psychic Mind","猛超能","超能属性招式1.2倍，HP1/3以下1.5倍",["输出位·超能力"]],["344","Poison Absorb","毒素吸收","受到毒属性招式攻击回复最大HP的1/4",[]],["345","Scavenger","清道夫","自身打倒精灵时回复最大HP的1/4",[]],["346","Twist. Dimension","空间扭曲者","入场时使用戏法空间，持续3回合",[]],["347","Multi-Headed","多头","自身有几个头就攻击几次",[]],["348","North Wind","极北之风","入场时释放极光幕，持续3回合，不受冰雹伤害",[]],["349","Overcharge","电力过载","电属性招式对电属性精灵伤害2倍，可以使电属性精灵麻痹",[]],["350","Violent Rush","暴力冲刺","入场第一回合速度+50%，攻击+20%",[]],["351","Flaming Soul","燃烧之魂","满HP时，火属性招式+1优先级",[]],["352","Sage Power","贤者之力","特攻提升50%,但锁定招式.\n特攻能力值提升50%,但会将使用者锁定在首次选择的招式上,直到替换下场.",[]],["353","Bone Zone","骨之领域","骨头类招式无视免疫，效果不好招式伤害2倍",[]],["354","Weather Control","天气掌控","对方天气相关招式无效",[]],["355","Speed Force","速之力","使用接触类招式时获得速度20%加成",[]],["356","Sea Guardian","海洋守护者","在雨天出场时,自身最高的能力值提升1级.\n在雨天天气下进入战斗时,海洋守护者使你最高的能力值提升1级.适用于任何形式的雨天.每次替换上场触发一次.",[]],["357","Molten Down","熔岩","火属性招式对岩石属性效果绝佳",[]],["358","Hyper Aggressive","好斗","招式攻击两次，第二次伤害25%",[]],["359","Flock","猛鸟","飞行属性招式1.2倍，HP1/3以下1.5倍",["输出位·飞行"]],["360","Field Explorer","大牙狸之佑","提高野外招式50%，居合斩、冲浪、碎岩等等",[]],["361","Striker","猛踢","踢类招式1.3倍",[]],["362","Frozen Soul","冰冻之魂","满HP时，冰属性招式+1优先级",[]],["363","Predator","强夺","自身打倒精灵时回复最大HP的1/4",[]],["364","Looter","掠夺","自身打倒精灵时回复最大HP的1/4",[]],["365","Lunar Eclipse","月蚀","妖精和恶属性获得属性一致加成，催眠术命中率1.5倍",["输出位·妖精、恶"]],["366","Solar Flare","耀斑","叶绿体+火焰皮肤，且火属性招式获得1.5倍属性一致加成",[]],["367","Power Core","力量中枢","攻击招式获得20%防御或特殊防御的加成",[]],["368","Sighting System","瞄准系统","招式必定命中.基础命中率低于80%的招式优先度降低.\n瞄准系统确保所有招式无视命中判定,必定命中.基础命中率低于80%的招式获得-3优先度.",[]],["369","Bad Company","坏朋友","暂未实装",[]],["370","Opportunist","取巧","如果目标HP低于一半，单一目标招式+1优先级",[]],["371","Giant Wings","巨大翅膀","翅膀类招式、风类招式、空气类招式1.25倍",[]],["372","Momentum","动量","接触类招式使用速度能力值进行伤害计算.\n接触类招式使用速度能力值而非攻击/特攻进行伤害计算.讲究围巾的效果不影响此特性.",[]],["373","Grip Pincer","蟹钳","50%概率束缚对方，对方处于束缚状态下无视其防御和闪避",[]],["374","Big Leaves","巨大树叶","叶绿体+叶绿素+收获+叶子防守+太阳之力",[]],["375","Precise Fist","精准拳击","拳类招式击中要害率+1，额外效果概率5倍",[]],["376","Deadeye","死亡之眼","必定命中，弓类波动类招式取对方防御特防种较低的一项计算伤害",[]],["377","Artillery","炮手","超级发射器招式必定命中，单体招式可以打中对方两个",[]],["378","Amplifier","放大器","声音类招式+30%伤害且可以打中对方两个",[]],["379","Ice Dew","引冰","受到冰属性招式攻击时免受伤害，攻击或特攻中更高的一项提升一段",[]],["380","Sun Worship","日光崇拜","晴天时能力值最高的一项上升一段",[]],["381","Pollinate","昆虫皮肤","一般属性的招式会变为虫属性，威力1.1倍",[]],["382","Volcano Rage","火山之怒","使用火属性招式后,触发威力50的喷火.\n使用任何火属性招式后,火山之怒会触发一次后续的喷火攻击,基础威力为50.伤害根据使用者当前的HP比例变化,满HP时威力为50.",[]],["383","Cold Rebound","冰冷回击","被接触类招式攻击时释放冰冻之风",[]],["384","Low Blow","卑鄙奇袭","入场时释放40威力的出奇一击",[]],["385","Nosferatu","吸血鬼","接触类招式+20%伤害，回复造成伤害一半的HP",[]],["386","Spectral Shroud","幽灵外壳","幽灵皮肤+30%概率使对方中剧毒",[]],["387","Discipline","纪律性","狂暴类招式不会混乱，不会被威吓",[]],["388","Thundercall","雷电召唤","使用电属性招式时触发20%威力的电力猛击",[]],["389","Marine Apex","海洋顶点","穿透+对水属性造成伤害+50%",[]],["390","Mighty Horn","大角","角类招式和钻类招式1.3倍",[]],["391","Hardened Sheath","坚固外壳","使用角类招式攻击+1",[]],["392","Arctic Fur","北极毛皮","减少物理和特殊招式伤害35%",[]],["393","Spectralize","幽灵皮肤","一般属性的招式会变为幽灵属性，威力1.1倍",[]],["394","Lethargy","无精打采","伤害每回合递减20%最低20%，重新入场重置",[]],["395","Iron Barrage","强大火力","超级发射器+瞄准系统",[]],["396","Steel Barrel","钢铁炮管","免疫反伤伤害",[]],["397","Pyro Shells","迸发炮弹","使用超级发射器招式时触发50威力的迸发",[]],["398","Fungal Infection","真菌感染","接触类招式对目标施加寄生种子.\n使用接触类招式时,对目标施加寄生种子,每回合结束时吸取目标1/8的最大HP.",[]],["399","Parry","招架","以音速拳反击接触攻击.受到的伤害降低20%.\n所有受到的伤害降低20%.与其他减伤来源乘法叠加.以威力20的音速拳反击接触类招式.",[]],["400","Scrapyard","废料场","受到接触招式攻击时,设置一层撒菱.\n当使用者成功被接触招式命中时,在对手场上设置一层撒菱.每层使替换上场的接地宝可梦分别损失最大HP的12.5%、16.7%或25%（对应1-3层）连续攻击招式的每一次命中都会设置一层.",[]],["401","Loose Quills","掉刺","受到接触招式攻击时撒菱",[]],["402","Toxic Debris","毒满地","受到接触招式攻击时撒毒菱",[]],["403","Roundhouse","大抡腿","踢类招式必定命中，取对方防御特防中较低的一项计算伤害",[]],["404","Mineralize","岩石皮肤","一般属性的招式会变为岩石属性，威力1.1倍",[]],["405","Loose Rocks","掉出岩屑","被攻击时撒下隐形岩",[]],["406","Spinning Top","回转攻击","使用格斗属性招式时速度上升一段，并且清空场地陷阱",[]],["407","Retribution Blow","惩罚光线","当对方使用属性上升类招式时释放破坏光线",[]],["408","Fearmonger","恐惧散布","威吓+恐吓，使用接触类招式10%概率使对方麻痹",[]],["409","King's Wrath","王之震怒","己方任意属性降低时会上升一段攻击和防御",[]],["410","Queen's Mourning","女王之哀悼","己方任意属性降低时会上升一段特攻和特防",[]],["411","Toxic Spill","剧毒散播","在场上时非毒属性精灵每回合受到1/8HP伤害",[]],["412","Desert Cloak","沙之披风","使得己方免受异常状态伤害和沙暴伤害",[]],["413","Draconize","龙族皮肤","一般属性的招式会变为龙属性，威力1.1倍",[]],["414","Pretty Princess","公主的恩赐","如果目标有被降低的属性，造成伤害+50%",[]],["415","Self Repair","自我修复","自给自足 + 自然回复.\n每回合结束时回复1/16的最大HP,并且替换下场时治愈所有异常状态.",[]],["416","Atomic Burst","原子爆炸","电力转换 + 电气皮肤.\n受到任何招式攻击时,使用者会进入充电状态,使下一次电属性招式威力加倍.将所有一般属性招式转变为电属性招式,并为电属性招式提供本系加成.如果使用者是电属性,其电属性招式有10%的几率造成麻痹.",[]],["417","Hellblaze","猛猛火","火属性招式1.3倍，HP1/3以下1.8倍",[]],["418","Riptide","激激流","水属性招式1.3倍，HP1/3以下1.8倍",[]],["419","Forest Rage","茂茂盛","草属性招式1.3倍，HP1/3以下1.8倍",[]],["420","Primal Maw","原始吞噬","咬类招式攻击两次，第二次0.4倍伤害",[]],["421","Sweeping Edge","大刃","劈砍类招式必定命中且单一目标招式攻击对方两个",[]],["422","Gifted Mind","天才思想","消除超能弱点，变化类招式必中",["免疫·恶","免疫·幽灵","免疫·虫"]],["423","Hydro Circuit","水电转化","电属性招式+50%，水属性招式回复造成伤害的25%",[]],["424","Equinox","二分点","使攻击和特殊攻击相等数值取其中更高的一项",[]],["425","Absorbant","超量吸收","吸取类招式回复50%并种下寄生种子",[]],["426","Clueless","一无所知","消除天气空间场地",[]],["427","Cheating Death","假死","免疫前两次受到的攻击伤害",[]],["428","Cheap Tactics","低劣战术","入场时释放抓",[]],["429","Coward","胆小","入场时释放守住，只生效一次",[]],["430","Volt Rush","伏特猛冲","满HP时，电属性招式+1优先级",[]],["431","Dune Terror","沙暴恐惧","沙暴天气时受到伤害-35%，地面属性招式+20%",[]],["432","Infernal Rage","地狱愤怒","火属性招式伤害+35%，但受到5%反伤",[]],["433","Dual Wield","双持","超级发射器和锐利刀刃类招式攻击两次并且每次造成70%伤害.\n通常只命中一次的超级发射器和锐利刀刃类招式现在会攻击两次,每次造成招式正常伤害的70%.追加效果在每次攻击中独立判定（畏缩除外）.",[]],["434","Elemental Charge","元素掌控","20%概率烧伤冻伤或者麻痹对方",[]],["435","Ambush","埋伏","上场的第一回合必定会心一击.\n埋伏特性在使用者替换上场后或战斗开始的第一回合,必定造成击中要害.",[]],["436","Atlas","引力神","入场释放重力，持续8回合",[]],["437","Radiance","光彩夺目","命中率+20%，当在场上时恶属性招式失效",[]],["438","Jaws of Carnage","屠杀之牙","打倒对方时回复其1/2HP",[]],["439","Angel's Wrath","天使暴怒","彻底更改所有招式",[]],["440","Prismatic Fur","棱镜毛皮","变色+变换自如+毛皮大衣+冰鳞粉",[]],["441","Shocking Jaws","感电下颚","咬类招式50%概率麻痹对方",[]],["442","Fae Hunter","妖精猎者","对妖精属性精灵造成伤害+50%",[]],["443","Gravity Well","重力井","入场释放重力，持续5回合",[]],["444","Evaporate","蒸发","受到水属性攻击时不受伤害并设置白雾.\n蒸发特性使受到的水属性招式伤害无效,并在受到水属性招式攻击时,为己方场上设置持续5回合的白雾.白雾保护全队免受能力降低,包括自身引起的降低.",["免疫·水","雨天免疫位"]],["445","Lumberjack","伐木工","对草属性宝可梦造成1.5倍伤害.受到草属性宝可梦攻击时,伤害减半.\n对草属性宝可梦造成1.5倍伤害,并且受到草属性宝可梦攻击时,伤害减半.此效果基于攻击方/防御方宝可梦的属性,而非招式属性.伤害减免与其他来源乘法叠加.",[]],["446","Well Baked Body","焦香之躯","被火属性招式攻击时免受伤害并提升2段防御",["免疫·火","晴天免疫位"]],["447","Furnace","熔炉","受到岩石属性招式或出场有隐形岩时速度提升2级.\n熔炉特性在受到岩石属性招式攻击时,或在存在隐形岩的情况下替换上场时,速度能力值提升2级.",[]],["448","Electromorphosis","电力转换","受到攻击时进入充电状态.\n受到任何招式攻击时,使用者会进入充电状态,使下一次电属性招式威力加倍.充电状态在使用一次电属性招式后消耗.",[]],["449","Rocky Payload","搬岩","岩石属性招式和投类招式1.5倍",["输出位·岩石"]],["450","Earth Eater","食土","受到地面属性招式攻击时,回复25%的最大HP.\n食土特性在受到地面属性招式攻击时,为该宝可梦回复其最大HP的25%.",[]],["451","Lingering Aroma","甩不掉的气味","被对手接触到后，甩不掉的气味会沾上对手。",[]],["452","Fairy Tale","童话","出场时添加妖精属性.\n进入战斗时,为使用者的当前属性添加妖精属性.即使失去此特性,添加的妖精属性在替换下场前依然保留.",[]],["453","Raging Moth","暴怒之蛾","火属性招式攻击两次，两次伤害均为70%",[]],["454","Adrenaline Rush","肾上腺素","打倒对方时速度上升一段",[]],["455","Archmage","大魔法师","30%概率为招式附加一个属性相关的特效",[]],["456","Cryomancy","冷冻学","冰属性招式冻伤概率5倍",[]],["457","Phantom Pain","幻痛","幽灵属性招式对一般属性造成正常伤害.\n幻痛特性移除一般属性对幽灵属性招式的免疫,允许幽灵属性攻击以1倍效果命中一般属性宝可梦.",[]],["458","Purgatory","猛猛鬼","幽灵属性招式1.3倍，HP1/3以下1.8倍",[]],["459","Emanate","超能皮肤","一般属性的招式会变为超能属性，威力1.1倍",[]],["460","Kunoichi's Blade","女忍者之刃","提升低威力招式伤害，增加多段招式的击中次数",[]],["461","Monkey Business","猴戏","入场释放挠痒",[]],["462","Combat Specialist","战斗专家","拳类和踢类招式1.3倍",[]],["463","Jungle's Guard","丛林守护","己方草属性精灵免疫对方给与的异常状态以及能力下降",[]],["464","Hunter's Horn","捕兽者之角","角类招式增强，打倒精灵时回复最大HP的1/4",[]],["465","Pixie Power","精灵之力","全场妖精属性招式威力增强1/3，命中率1.2倍",[]],["466","Plasma Lamp","等离子灯","火属性和电属性招式的命中率和威力提升1.2倍.\n等离子灯使火属性和电属性招式的威力和命中率各提升20%.",[]],["467","Magma Eater","岩浆吞噬者","强夺+熔岩",[]],["468","Super Hot Goo","灼热粘液","接触时给予对方灼烧以及降低对方一段速度",[]],["469","Nika","海滨拳手","铁拳+水属性招式在晴天下威力正常",[]],["470","Archer","弓手","弓类招式1.3倍",[]],["471","Cold Plasma","低温电浆","电属性招式会造成烧伤代替麻痹",[]],["472","Super Slammer","大锤","锤类招式和撞类招式1.3倍",[]],["473","Inversion","反转空间","入场释放反转场地，持续3回合",[]],["474","Accelerate","加速度","蓄力类招式直接释放",[]],["475","Frost Burn","霜火","使用火属性招式后触发40威力的冰冻光束",[]],["476","Itchy Defense","痒痒防御","被接触类招式攻击后释放纠缠不休",[]],["477","Generator","发电机","出场时或电气场地激活时进入充电状态.\n发电机在替换上场时使使用者进入充电状态,下一次电属性招式威力加倍.在战斗中电气场地激活时再次充电.充电状态在替换下场或使用一次电属性招式后消失.",[]],["478","Moon Spirit","月之意志","妖精和恶属性获得属性一致加成，月光回复最大HP的3/4",[]],["479","Dust Cloud","扫去灰尘","入场使用泼沙",[]],["480","Berserker Rage","狂战士之怒","临界点 + 暴走.\n受到攻击时,特攻提升1级；受到击中要害时,特攻提升至最大.击倒对手时,立即从休息状态中恢复,允许立即使用破坏光线等招式而无需等待.",[]],["481","Trickster","戏法师","入场使用定身法",[]],["482","Sand Guard","沙漠守护","对方无法对我方使用先制招式，沙暴下特殊伤害减半",[]],["483","Natural Recovery","自然痊愈","自然回复+再生力",[]],["484","Wind Rider","乘风","在顺风中出场或被风类招式命中时,提升攻击能力.\n在顺风状态下进入战斗时,提升使用者最高的攻击能力值.受到风类招式攻击时,吸收该攻击并使最高的攻击能力值提升1级.",[]],["485","Soothing Aroma","平静芳香","入场治愈己方队伍异常状态",[]],["486","Prim and Proper","高贵优雅","奇迹皮肤+迷人之躯",[]],["487","Super Strain","高压","打到对方时下降一段攻击，攻击受到25%反伤",[]],["488","Tipping Point","临界点","受到攻击时,特攻提升1级.受到击中要害时提升至最大.\n受到攻击时,该宝可梦的特攻提升1级；若受到击中要害的攻击,则特攻能力值提升至最大.对于连续攻击招式,每次命中都会触发.",[]],["489","Enlightened","顿悟","超能皮肤+精神力",[]],["490","Peaceful Slumber","安然入睡","美梦+自给自足",[]],["491","Aftershock","余震","使用造成伤害的招式后,触发震级4-7.\n在使用造成伤害的招式命中后,使用者紧接着使用震级,威力为10、30、50或70.攻击所有相邻的宝可梦.",[]],["492","Freezing Point","冰点","接触类招式30%概率使对方冻伤",[]],["493","Cryo Proficiency","寒冰精通","被击时释放冰雹天气，接触类招式30%概率使对方冻伤",[]],["494","Arcane Force","神秘之力","所有属性都获得1.5倍属性一致加成，效果绝佳招式伤害+10%",[]],["495","Doombringer","毁灭者","入场时释放破灭之愿",[]],["496","Wishmaker","祁愿者","入场时释放祁愿，一场战斗只能触发三次",[]],["497","Yuki Onna","冰女","威吓+恐吓，攻击时10%概率着迷",[]],["498","Suppress","压制","出场时使用无理取闹.\n出场时使用无理取闹,阻止对手连续使用相同的招式.",[]],["499","Refrigerator","冰箱","冰冻皮肤+发光",[]],["500","Heaven Asunder","撕裂虚空","亚空裂斩必定击中要害，击中要害率上升一段",[]],["501","Purifying Waters","纯净水","湿润之躯+水幕",[]],["502","Seaborne","海之子","降雨+悠游自如",[]],["503","High Tide","满潮","使用水系招式后释放50威力的冲浪",[]],["504","Change of Heart","灵魂互换","入场释放心灵互换",[]],["505","Mystic Blades","神秘之刃","劈砍类招式造成特殊伤害且威力1.3倍",[]],["506","Determination","决心","处于异常状态时,特攻提升50%.\n当该宝可梦处于任何异常状态时,其特攻能力值提升50%.同时防止冻伤状态降低特攻.",[]],["507","Fertilize","青草皮肤","一般属性的招式会变为草属性，威力1.1倍",[]],["508","Pure Love","纯爱","接触时使对方着迷，攻击着迷状态对象时回复造成伤害的25%",[]],["509","Fighter","猛斗","格斗属性招式1.2倍，HP1/3以下1.5倍",["输出位·格斗"]],["510","Mycelium Might","菌丝之力","变化招式无视免疫,但必定后手.\n允许变化招式穿透所有免疫和属性抗性,但会强制其在当前优先度层级内最后行动.",[]],["511","Telekinetic","隔空取物","入场时释放意念移物",["免疫·地面","地面免疫位"]],["512","Combustion","燃烧","火属性招式威力提升至1.5倍.\n燃烧使所有火属性招式的威力提升50%.",["输出位·火"]],["513","Blade's Essence","小马之力","锐利之刃+神秘之刃",[]],["514","Powder Burst","撒粉","入场释放粉尘",[]],["515","Retriever","寻回鼠","换出时取回道具",[]],["516","Monster Mash","捣蛋怪","入场时释放万圣夜",[]],["517","Two Step","跟舞","使用舞类招式后触发50威力的觉醒之舞",[]],["518","Spiteful","怀恨在心","被接触攻击时减少对方PP",[]],["519","Fortitude","刚毅","受到攻击时,特防提升1级.受到击中要害时,特防提升至最大.\n受到攻击时,该宝可梦的特防提升1级；若受到击中要害的攻击,则特防能力值提升至最大.对于连续攻击招式,每次命中都会触发.",[]],["520","Devourer","吞噬者","强壮之颚 + 原始颚.\n使啃咬类招式威力提升30%.所有啃咬类招式攻击两次.第一击造成100%伤害,第二击造成40%伤害.每次攻击独立判定追加效果.",[]],["521","Phantom Thief","幻影盗贼","入场时释放40威力的暗影偷盗",[]],["522","Early Grave","墓地冲刺","满HP时，幽灵属性招式+1优先级",[]],["523","Grappler","钩爪","束缚类招式持续6回合，且每回合HP减少1/6",[]],["524","Bass Boosted","强力低音","放大器+庞克摇滚",[]],["525","Flaming Jaws","火焰之牙","咬类招式50%概率烧伤目标",[]],["526","Monster Hunter","怪物猎人","对恶属性宝可梦造成1.5倍伤害.受到恶属性宝可梦攻击伤害减半.\n对恶属性宝可梦造成1.5倍伤害,并且受到恶属性宝可梦攻击时,伤害减半.此效果基于攻击方/防御方宝可梦的属性,而非招式属性.伤害减免与其他来源乘法叠加.",[]],["527","Crowned Sword","王冠之剑","不挠之剑+愤怒穴位",[]],["528","Crowned Shield","王冠之盾","不屈之盾+持久力",[]],["529","Berserk DNA","狂战士之魂","入场攻击或特攻更高一项上升2段但进入混乱状态",[]],["530","Crowned King","加冕为王","紧张感+苍白嘶鸣+漆黑嘶鸣",[]],["531","Clap Trap","反夹","受到接触攻击时触发50威力捕兽夹进行反击",[]],["532","Permanence","永恒禁疗","对方单位无法以任何方式回复",[]],["533","Hubris","狂妄","打倒对手时提升一段特攻",[]],["534","Cosmic Daze","无边眩晕","对混乱状态对象造成伤害翻倍，混乱对象对自己造成伤害时也翻倍",[]],["535","Mind's Eye","心眼","可以命中幽灵属性宝可梦.命中率不会被降低.\n心眼允许一般属性和格斗属性招式以普通效果命中幽灵属性宝可梦.此外,此特性防止使用者的命中率被对手的招式或特性降低.",[]],["536","Blood Price","血之代价","造成伤害+30%，但攻击时损失最大HP10%",[]],["537","Spike Armor","尖刺护甲","接触类招式30%概率使对方进入流血状态",[]],["538","Voodoo Power","巫术之力","被特殊类招式攻击时30%概率使对方进入流血状态",[]],["539","Chrome Coat","合金外壳","受到的特殊伤害-40%，但自身速度-10%",["减伤·特殊"]],["540","Banshee","猛鬼之声","一般属性的招式会变为幽灵属性，威力1.2倍",[]],["541","Web Spinner","纺织工","入场时释放吐丝",[]],["542","Showdown Mode","对决模式","埋伏+暴力冲刺",[]],["543","Seed Sower","掉出种子","受到攻击时布下青草场地并治愈己方队伍的状态",[]],["544","Airborne","飞空助力","自己和队友飞行属性招式1.3倍",[]],["545","Parroting","鹦鹉学声","有谁使出声音招式时也接着使出声音招式，自己免疫声音招式",[]],["546","Salt Circle","盐之包围","入场时阻止对方换人（幽灵属性精灵不受影响）",[]],["547","Purifying Salt","洁净之盐","不会陷入异常状态，幽灵属性的招式伤害减半",["减伤·幽灵"]],["548","Protosynthesis","古代活性","在大晴天或携带驱劲能量时,提升最高的能力.\n在大晴天下,使用者最高的能力值提升（速度提升50%,其他提升30%）.大晴天结束时,如果携带驱劲能量则激活.此效果视为原始能力提升而非能力等级变化.除非被单纯光束或烦恼种子影响,否则无法被复制、压制或替换.",[]],["549","Quark Drive","夸克充能","在电气场地或携带驱劲能量时,提升最高的能力.\n在电气场地中,使用者最高的能力值提升（速度提升50%,其他提升30%）.场地结束时,如果携带驱劲能量则激活.此效果视为原始能力提升而非能力等级变化.除非被单纯光束或烦恼种子影响,否则无法被复制、压制或替换.",[]],["550","Wind Power","风力发电","受到风类招式或在顺风中出场时进入充电状态.\n受到基于风的招式攻击或在顺风中进入战斗时,获得充电状态.充电状态使下一次电属性招式威力加倍,直到使用为止.",[]],["551","Impulse","脉冲","非接触类招式使用速度能力值进行伤害计算.\n非接触类招式使用速度能力值而非攻击/特攻进行伤害计算.讲究围巾的效果不影响此特性.",[]],["552","Terminal Velocity","终结速度","特攻招式伤害获得速度的20%加成",[]],["553","Guard Dog","看门犬","受到威吓时攻击上升一段，不会被对方影响而离场",[]],["554","Anger Shell","愤怒甲壳","当HP降至1/2以下时,触发破壳.\n当HP降至50%以下时,使用者触发破壳效果：攻击、特攻和速度各提升2级,同时防御和特防各降低1级.每场战斗仅触发一次.在连续攻击的最后一击后触发.",[]],["555","Egoist","跟风","对手的能力提高时，自己也会趁机同样地提高能力。",[]],["556","Subdue","能力压制","使能力下降的招式或特性效果翻倍",[]],["557","Readied Action","准备充分","入场第一回合攻击翻倍",[]],["558","Stygian Rush","地狱冲刺","满HP时，恶属性招式+1优先级",[]],["559","Guilt Trip","负罪礼物","被打倒时降低对方攻击和特攻两段",[]],["560","Tidal Rush","潮汐加速","满HP时，水属性招式+1优先级",[]],["561","Zero To Hero","全能变身","回到同行队伍后，会变为全能形态。",[]],["562","Costar","同台共演","出场时复制同伴的能力变化.\n在双打对战中替换上场时,同台共演复制同伴的所有能力等级变化（包括正向和负向）.",[]],["563","Commander","发号施令","出场时，会进入吃吼霸口中，并从其口中发出指令",[]],["564","Tactical Retreat","战术撤退","能力被降低时逃走.\n当使用者的任何能力被降低时（包括自身引起的能力降低）,自动替换下场.每场战斗触发一次.",[]],["565","Vengeful Spirit","复仇之魂","作祟的魂魄 + 复仇.\n当被直接攻击击倒时,对攻击者施加诅咒.诅咒每回合造成其最大HP25%的伤害,直到被诅咒的宝可梦替换下场或濒死.幽灵属性的攻击者免疫此诅咒.幽灵属性招式威力提升30%,当HP低于1/3时提升50%.",[]],["566","Cud Chew","反刍","消耗树果后,在下一回合结束时再次食用.\n消耗树果时,使用者在下一回合结束时再次食用该树果.",[]],["567","Armor Tail","尾甲","保护自身及同伴免受先制招式影响.\n防止使用者和它的同伴成为优先度大于0的先制招式的目标.",[]],["568","Mind Crunch","心灵破坏","咬类招式变为特攻，伤害+50%",[]],["569","Supreme Overlord","大将","出场时，攻击和特攻会按目前被打倒的同伴数量提升，每个10%",[]],["570","Ill Will","恶意诅咒","被打倒时，对方打倒本精灵的招式PP归零",[]],["571","Fire Scales","火鳞粉","受到的特殊伤害减半",["减伤·特殊"]],["572","Watch Your Step","钉满地","入场时撒菱两次",[]],["573","Rapid Response","急速响应","入场第一回合特攻+20%，速度+50%",[]],["574","Sharp Edges","粗糙刃甲","受到接触类招式攻击时，对方受到1/6HP的伤害",[]],["575","Thermal Exchange","热交换","受到火属性攻击时,攻击提升.免疫灼伤.\n受到火属性招式攻击时,攻击提升1级,并且免疫灼伤状态.攻击提升在受到火属性攻击的伤害后立即生效.对于连续攻击招式,每次命中都会触发.",[]],["576","Good As Gold","黄金之躯","免疫所有变化招式,除非影响全场.\n黄金之躯免疫所有直接以该宝可梦为目标的变化招式.但仍会受到影响全场的黑雾等变化招式影响.",[]],["577","Sharing Is Caring","爱之共享","状态变化全场相同",[]],["578","Tablets Of Ruin","灾祸之简","降低其他宝可梦的攻击25%.\n在使用者在场时,降低所有其他宝可梦的攻击能力值25%.多个相同的灾祸特性效果不叠加与攻击降低效果乘法叠加.",[]],["579","Sword Of Ruin","灾祸之剑","降低其他宝可梦的防御25%.\n在使用者在场时,降低所有其他宝可梦的防御能力值25%.多个相同的灾祸特性效果不叠加与防御降低效果乘法叠加.",[]],["580","Vessel Of Ruin","灾祸之鼎","降低其他宝可梦的特攻25%.\n在使用者在场时,降低所有其他宝可梦的特攻能力值25%.多个相同的灾祸特性效果不叠加与特攻降低效果乘法叠加.",[]],["581","Beads Of Ruin","灾祸之玉","以能呼唤灾厄的玉的力量降低除自己以外的宝可梦的特防1/4",[]],["582","Thick Skin","厚皮肤","受到效果绝佳的攻击时，受到伤害减少25%",[]],["583","Gallantry","英勇","第一次受到的伤害无效.\n使第一次受到的伤害变为0.招式仍会连接且附加效果生效,但伤害变为0.",[]],["584","Orichalcum Pulse","绯红脉动","出场时降下大晴天.在大晴天下,攻击提升至1.33倍.\n出场时降下大晴天,持续8回合（携带炎热岩石时为12回合）.在大晴天下,使用者的攻击能力值提升33%.",["天气手·晴"]],["585","Sun Basking","晒太阳","晴天时阻止对方使用先制招式，受到物理招式伤害减半",[]],["586","Winged King","翼之王","效果绝佳招式威力1.3倍",[]],["587","Hadron Engine","强子引擎","出场时制造电气场地.在电气场地上,特攻提升33%.\n出场时制造电气场地,持续8回合（携带场地制造机时为12回合）.在电气场地上,使用者的特攻能力值提升33%.",[]],["588","Iron Serpent","钢铁巨蛇","效果绝佳招式威力1.3倍",[]],["589","Catastrophe","水火交融","晴天提高水属性伤害，雨天提高火属性伤害",[]],["590","Blademaster","剑圣","大刃+锐利之刃",[]],["591","Celestial Blessing","妖精祝福","博物场地下每回合回复最大HP的1/12",[]],["592","Minion Control","爪牙掌控","每有一个活着的队友，招式就攻击几次",[]],["593","Molten Blades","融化之刃","锐利之刃+劈砍类招式20%概率烧伤对方",[]],["594","Haunting Frenzy","狂乱萦绕","20%概率使对方畏缩，打到对方时速度上升一段",[]],["595","Noise Cancel","噪音过滤","保护友方免受声音类招式影响",[]],["596","Radio Jam","爵士广播","声音类招式20%概率额外附加定身法",[]],["597","Olé!","斗牛士","30%概率回避单体目标的招式",[]],["598","Malicious","恶意","降低对方攻击或特攻以及防御或特防一段(都取数值更高的一项)",[]],["599","Dead Power","地狱之力","攻击1.5倍，接触类招式攻击时20%概率诅咒对方",[]],["600","Brawling Wyvern","龙族拳手","无防守+龙属性招式变为拳类招式",[]],["601","Mythical Arrows","神秘箭矢","弓类招式造成特殊伤害且威力1.3倍",[]],["602","Lawnmower","割草机","出场时移除当前场地.若移除场地,则能力提升.\n替换上场时,移除任何激活的场地,并获得能力提升：移除青草或电气场地时,防御+1；移除薄雾、精神或剧毒场地时,特防+1.",[]],["603","Flourish","茁壮成长","草场上草属性招式+50%",[]],["604","Desert Spirit","沙漠意志","入场扬起沙暴，地面系招式在沙暴下可以击中飞空单位",["天气手·沙"]],["605","Contempt","蔑视","纯朴 + 不服输.\n进行伤害计算时,完全无视对手的所有能力等级变化.当该宝可梦的能力被其他宝可梦降低时,其攻击能力提升2级.",[]],["606","Aerialist","高空杂技","飘浮+猛鸟",["免疫·地面","地面免疫位"]],["607","Tera Shell","太晶甲壳","HP全满时,所有攻击都将变得效果不好.\n当HP全满时,所有对该宝可梦的攻击都将造成效果不好的伤害,无论属性相性如何.与其他类似特性不同,此效果在连续攻击的每次命中都会激活.",[]],["608","Toxic Chain","毒锁链","招式有30%几率使对手陷入剧毒.\n使用者在使用任何招式命中后,有30%的几率使目标陷入剧毒连续攻击的每一击都会独立判定.",[]],["609","Parasitic Spores","寄生孢子","每回合对非幽灵属性造成1/8HP伤害.接触时传播.\n出场时获得寄生孢子.每回合,受影响的宝可梦损失1/8最大HP（幽灵属性免疫）.使用接触招式时,将孢子传播给目标.孢子持续到替换下场.",[]],["610","Poison Puppeteer","毒傀儡","使对方陷入中毒状态时，同时对方也会陷入混乱状态",[]],["611","Entrance","魅惑","使对方陷入混乱状态时，同时对方也会陷入着迷状态",[]],["612","Rejection","驳回","入场时使用延后",[]],["613","Apple Enlightenment","苹果款待","毛皮大衣+魔法防守",[]],["614","Balloon Bomb","爆炸气球","引爆+充气",[]],["615","Flaming Maw","火焰吞噬","强壮之颚+火焰之牙",[]],["616","Demolitionist","爆破专家","准备就绪 + 无视保护 + 在准备回合击破屏障.\n使用者的攻击能力值在一回合内变为2倍,击破屏障,并无视保护效果.与其他伤害加成效果乘法叠加.替换下场后再次上场可重新触发.",[]],["617","Rockhard Will","猛岩","岩石属性招式1.2倍，HP1/3以下1.5倍",["输出位·岩石"]],["618","Fragrant Daze","芬芳迷惑","接触时30%使对手混乱",[]],["619","Low Visibility","低能见度","出场时召唤诡异迷雾.\n出场时召唤诡异迷雾,持续8回合（携带烟雾球时为12回合）.迷雾每回合减少非幽灵/超能力属性宝可梦的1级能力提升,使基于天气的回复效果减半,给予幽灵/超能力属性宝可梦20%的伤害减免,并将所有诅咒转变为幽灵属性的诅咒.",[]],["620","Old Mariner","老水手","海草 + 水系本系.\n如果使用者是草属性,其受到的火属性攻击伤害减半,并且使用草属性招式对火属性宝可梦造成2倍伤害.伤害减免与其他来源乘法叠加.使水属性招式获得本系加成,无论使用者的属性如何.同时免疫浸水状态.",[]],["621","Ectoplasm","流质","浓雾天气下，攻击特攻较高的一项1.5倍",[]],["622","Beautiful Music","美妙音乐","声音类招式有50%几率造成着迷,无视性别.\n声音类招式在命中时有50%的几率使目标着迷（将其攻击和特攻减半）.",[]],["623","Surprise!","吓一跳","浓雾天气下对方使用先制招式会用惊吓打断该招式",[]],["624","Snow Song","雪之歌","声音类招式获得1.2倍威力加成,若为一般属性则变为冰属性.\n使所有声音类招式的威力提升20%,并将一般属性的声音类招式转变为冰属性.",[]],["625","Greater Spirit","精神集中","浓雾天气下，入场时最高的一项属性+1",[]],["626","Resonance","共鸣","声音类招式有50%几率造成流血.\n声音类招式在命中时有50%的几率造成流血.流血每回合造成1/16最大HP伤害,阻止回复,并使能力等级效果无效.岩石和幽灵属性免疫流血.",[]],["627","Ethereal Rush","缥缈奔腾","浓雾天气下速度1.5倍",[]],["628","Pretty Privilege","妖精先兆","满HP时，妖精类招式先制度+1",[]],["629","Shallow Grave","薄葬","浓雾天气下，倒下可以以1/4生命复活一次",[]],["630","Menacing Situation","气势汹汹","20%几率使接触的精灵陷入恐惧状态，被接触也算",[]],["631","Shiny Lightning","耀眼闪电","命中率1.2倍，打雷必定命中",[]],["632","Terrify","恐恐吓","降低对方特攻2段",[]],["633","Ice Downfall","碎冰","受到接触类招式攻击时，反击60威力的冰柱坠击",[]],["634","Last Stand","背水一战","防御和特防随HP降低而提升,最高1.6倍.\n防御和特防能力值随HP降低线性提升.倍率从HP全满时的1.0倍提升至HP0%时的1.6倍.HP50%时提供1.3倍加成,HP25%时提供1.45倍加成.",[]],["635","Pyroclastic Flow","火岩浆流","熔岩+腐蚀",[]],["636","Blood Bath","鲜血之浴","免疫流血，造成流血时，同时使对方陷入恐惧状态",[]],["637","Battle Aura","战斗光环","该精灵在场时大幅提高所有精灵击中要害概率",[]],["638","Bloodlust","嗜血","血浴 + 噬魂.\n免疫流血状态.当该宝可梦成功使对手流血时,也使其陷入恐惧.恐惧束缚目标2回合,使其受到的伤害增加50%.如果被吹飞等招式强制替换,目标会摆脱恐惧.通过直接攻击击倒对手时,回复25%的最大HP.",[]],["639","Piercing Solo","穿刺独奏","声音类招式30%概率造成流血",[]],["640","Rhythmic","节奏大师","每使用一次重复招式，造成的伤害+10%",[]],["641","Chunky Bass Line","厚重低音","使用声音类招式后,触发威力40的地震.\n在使用任何声音类招式命中后,使用者紧接着使用威力40的地震,攻击所有相邻的宝可梦.",[]],["642","Jackhammer","重锤","撞类招式以70%威力攻击两次",[]],["643","Denting Blows","铿锵打击","锤类招式降低对方防御",[]],["644","Ice Cold Hunter","冰冷猎手","好斗+冰天雪地",[]],["645","Soul Crusher","灵魂锤击","锤类招式变为特殊招式且1.1倍",[]],["646","Arc Flash","弧闪","被攻击时50%概率使对方烧伤，攻击时50%概率使对方麻痹",[]],["647","Unicorn","独角兽","强大之角 + 妖精皮肤.\n使角和钻类攻击的威力提升30%.将一般属性招式转变为妖精属性并获得妖精属性本系加成.如果使用者是妖精属性,其妖精属性招式有10%的几率造成着迷.",[]],["648","On the Prowl","伺机徘徊","入场第一回合招式先制度+1，负先制度招式变为0先制度",[]],["649","Pretentious","自命不凡","击倒对手时,击中要害率提升1级.\n每当使用者通过直接攻击击倒对手时,其击中要害率提升1级.",[]],["650","Venoblaze Pincers","毒焰钳","物理招式威力提升1.2倍,并有20%几率造成灼伤或中毒.\n所有物理招式威力提升20%,并且接触时有20%的几率造成灼伤或中毒.",[]],["651","Eternal Blessing","永恒祝福","天之恩泽 + 再生力.\n在薄雾场地中,每回合结束时回复使用者最大HP的1/12.替换下场时,回复33%的最大HP.此回复效果不受回复封锁影响.",[]],["652","Sugar Rush","吃果","贪吃鬼且受到接触类招式攻击时吃掉对方的树果",[]],["653","Rest in Peace","雾眠","浓雾天气时，每回合回复最大HP的1/8",[]],["654","White Noise","白噪音","静电 + 安息.\n无论该宝可梦是攻击方还是被攻击方,都有几率使对手陷入麻痹.非接触攻击有10%几率麻痹,接触攻击有30%几率麻痹.在迷雾中时,每回合结束时回复使用者最大HP的1/8.",[]],["655","Smokey Maneuvers","烟雾弹","浓雾天气下回避率1.25倍",[]],["656","Tag","标靶","对换场的精灵释放一个20威力的追打",[]],["657","Power Metal","金属力量","声音类招式1.2倍，且一般系变为钢系",[]],["658","Power Edge","力量之刃","锐利刀刃类招式攻击特防,并获得1.3倍威力加成.\n锐利刀刃类招式获得30%的伤害加成,并且伤害计算时目标改为特防而非防御.",[]],["659","Superconductor","超导体","钢属性招式变为电属性,并获得1.1倍威力加成.\n所有钢属性招式转变为电属性,并获得10%的威力提升.",["转换位·电（源钢）"]],["660","Ultra Instinct","超本能","受到接触类招式伤害反击真空波，受到伤害-20%",[]],["661","Unlocked Potential","解锁潜能","精神力+怒火冲天",[]],["662","Higher Rank","先行之力","先制招式威力+20%",[]],["663","Funeral Pyre","死灵之火","非幽灵系或恶系精灵每回合受到1/4最大HP的伤害",[]],["664","Flame Bubble","火焰泡泡","水泡+燃烧之魂",[]],["665","Elemental Vortex","元素漩涡","引火 + 储水.\n免疫火属性和水属性招式.受到火属性招式攻击时,自身该类招式威力提升50%,直到下场.受到水属性招式攻击时,回复最大HP的25%.",["免疫·火","免疫·水","雨天免疫位","晴天免疫位"]],["666","Snowy Wrath","雪怒","降雪+冰天雪地",[]],["667","Pattern Change","自由变型","变为与自己使出的招式相同的属性。",[]],["668","No Turning Back","义无反顾","当HP低于1/2时,全能力提升,但无法撤退.\n当HP首次降至一半或以下时,所有能力提升1级,且使用者无法替换或逃走.常规的绕过此效果的方式（如逃脱按键或逃脱按键）仍然允许替换.",[]],["669","Flammable Coat","易燃表皮","使用火系招式或被火系招式攻击改变形态",[]],["670","Draco Morale","龙族斗志","入场时释放龙声鼓舞",[]],["671","Bad Omen","凶兆","对方造成伤害取最低随机数，受到击中要害伤害为1/4",[]],["672","Mosh Pit","劲舞区","友方攻击伤害1.25倍，如果是反伤类招式则伤害1.5倍",[]],["673","Blood Stain","血污","不免疫的话，自身陷入流血且不会陷入其他状态，接触时传播该特性",[]],["674","Blood Stigma","血痕","不会陷入异常状态，对流血状态敌方造成伤害+50%",[]],["675","Max Acceleration","最大加速度","招式使用速度作为伤害计算",[]],["676","Sidewinder","响尾蛇","每次出场第一次使用的啃咬类招式获得+1优先度.击倒对手时重置.\n出场时,赋予第一次使用的啃咬类招式+1优先度.在使用任何啃咬类招式命中后,该优先度加成即被消耗.通过直接攻击击倒对手后,重新获得优先度增益.",[]],["677","Petrify","石化","出场时清除对手的能力提升,然后降低其速度1级.\n移除对手宝可梦的能力提升,然后降低其速度1级.",[]],["678","Fluffiest","极致蓬松","受到接触类招式伤害减少为1/4，受到火属性招式伤害4倍",[]],["679","Way of Precision","精准之道","精神力+精准拳击",[]],["680","Way of Swiftness","迅捷之道","自命不凡 + 悠游自如.\n每当使用者通过直接攻击击倒对手时,其击中要害率提升1级.下雨天气时,该宝可梦的速度提升50%.",[]],["681","Atomic Punch","原子拳","铁拳 + 30%钢属性伤害.",[]],["682","Iron Giant","钢铁巨人","耐热+重型坦克",[]],["683","Master Hand","大师之手","超级发射器 + 暴走.\n使脉冲、波导、波动和光环类招式威力提升30%.击倒对手时,立即从休息状态中恢复,允许立即使用破坏光线等招式而无需等待.",[]],["684","Final Blow","致命强击","无影拳+精准致命",[]],["685","Hospitality","款待","入场时回复同伴最大HP的1/4",[]],["686","Butter Up","热情款待","款待+平静芳香",[]],["687","Vitality Strike","活力打击","使用拳类招式造成伤害时,回复伤害量10%的HP.\n使用拳类招式造成伤害时,回复相当于伤害量10%的HP.",[]],["688","Imposing Wings","巨翼","巨大翅膀+飘浮",["免疫·地面","地面免疫位"]],["689","Sword of Damnation","诅咒之剑","纯朴 + 灾祸之剑.\n在使用者在场时,降低所有其他宝可梦的防御能力值25%.多个相同的灾祸特性效果不叠加进行伤害计算时,完全无视对手的所有能力等级变化.",[]],["690","Restraining Order","禁令","当受到攻击时强制对方下场，每次入场生效一次",[]],["691","Assassin's Tools","刺客工具","接触类招式有30%几率造成中毒、麻痹或流血.\n当使用者使用接触类招式命中时,有30%的几率随机使目标陷入中毒、麻痹或流血状态.连续攻击的每一击都会独立判定.",[]],["692","Frostmaw","冰霜之牙","咬类招式50%概率造成冻伤",[]],["693","Patchwork","诅咒之皮","画皮+当画皮被打破诅咒对方",[]],["694","Blind Rage","失控之怒","胆量+破格",[]],["695","Slipstream","滑流","使用攻击时,额外使用20%的速度能力值.\n使用攻击时,将使用者20%的速度能力值加入伤害计算.讲究围巾的效果不影响此特性.",[]],["696","Apex Predator","顶级掠夺","硬爪+强夺",[]],["697","Dragon's Ritual","龙之仪式","击倒对手时,攻击和速度各提升1级.\n每当使用者通过直接攻击击倒对手时,其攻击和速度能力值各提升1级.",[]],["698","Pinnacle Blade","巅峰之刃","劈开类招式必定命中,且能穿透保护和屏障.\n所有锐利刀刃类招式必定命中,并且可以穿透保护类招式,忽略与其相关的任何附加效果.",[]],["699","Energized","通电","发电机+电系招式打倒对方时自身充电",[]],["700","Color Spectrum","彩色光谱","同属性招式1.2倍，自身属性每回合变化",[]],["701","Steel Beetle","钢铁甲虫","暴怒拳手+昆虫皮肤",[]],["702","From the Shadows","源于阴影","比对方先行动时会束缚对方且20%概率造成畏缩",[]],["703","Rage Point","愤怒点","处于异常状态时造成伤害1.5倍，被击中要害时提高攻击和特攻",[]],["704","Hot Coals","热炭","布下一个陷阱使下一个换上场的敌方烧伤",[]],["705","Terastal Treasure","太晶宝藏","受到的伤害降低40%,但速度降低20%.\n受到的伤害降低40%,同时该宝可梦的速度降低20%.与其他减伤来源乘法叠加.",[]],["706","Shocking Maw","充电巨口","强壮之颚+咬类招式50%概率造成麻痹",[]],["707","Gleam Eyes","闪烁之眼","察觉+恐吓",[]],["708","Megabite","超级咬力","咬类招式使用特攻结算，且1.3倍",[]],["709","Dream State","梦境","免疫击中要害.受到的招式伤害降低20%.\n受到的伤害降低20%（x0.8）,与其他减伤效果乘法叠加.此外,免疫击中要害,会心一击将作为普通攻击处理,并且不会触发攻击要害的效果（例如“至骨”的流血效果）.",[]],["710","Dream Whimsy","梦境意念","入场时释放哈欠",[]],["711","Lunar Affinity","月之亲和","模仿其他宝可梦使用的月亮相关招式.\n当其他宝可梦在战斗中使用月亮相关招式时,进行模仿.包括月光、月亮之力、月之舞和月之祝福.每回合对每个招式触发一次.",[]],["712","Flame Shield","火焰之盾","受到效果绝佳的攻击时，受到伤害减少35%",[]],["713","Aquatic Dweller","水栖栖息者","水属性招式1.5倍",["输出位·水"]],["714","Apple Pie","苹果派","自给自足 + 熟成.\n每回合结束时回复1/16的最大HP.熟成使所有树果的有益效果加倍回复类树果回复量加倍,提升能力的树果改为提升2级,抵抗树果将效果绝佳的伤害降低75%,回复PP的树果回复20 PP.",[]],["715","Hover","意念悬浮","自身获得超能属性，免疫地面属性攻击",["免疫·地面","地面免疫位"]],["716","Depravity","腐化","不仁不义+电力过载",[]],["717","Wildfire","野火","出场时使用火焰旋涡.\n替换上场时使用火焰旋涡,威力50的火属性特殊招式,束缚对手4-5回合.目标每回合损失1/8最大HP,且在束缚结束前无法替换下场.",[]],["718","Jumpscare","惊吓礼物","第一次入场时释放一次惊吓",[]],["719","Tar Toss","焦油投掷","出场时使用掷焦油.\n替换上场时使用掷焦油,降低目标速度1级,并使其受到的火属性伤害变为2倍.后续使用不会叠加火属性伤害的负面效果.",[]],["720","Stun Shock","眩晕冲击","攻击60%概率造成麻痹或中毒",[]],["721","Raging Goddess","狂暴女神","狂暴+好斗",[]],["722","Whiplash","鞭笞","物理招式50%概率降低对方防御",[]],["723","Supersweet Syrup","超甜糖浆","黏着 + 接触时使对手物品失效2回合.\n该宝可梦携带的物品不会被强制移除或偷走.发生接触时,对手的物品失效2回合.",[]],["724","Lucky Halo","幸运光环","无视自身能力降低.抵挡一次濒死攻击.\n防止使用者自身引起的能力降低,并允许其承受一次会使其濒死的攻击,留下1点HP.",[]],["725","Trash Heap","垃圾堆","腐蚀 + 毒溢.\n毒属性招式对钢属性宝可梦变得效果绝佳.此外,该宝可梦可以使任何属性的宝可梦陷入中毒状态.每回合伤害所有非毒属性宝可梦,造成其1/8的HP损失.拥有毒疗特性的宝可梦反而会回复.使用者下场时效果消失.",[]],["726","Sludgy Mix","泥浆混合物","剧毒皮肤+庞克摇滚",[]],["727","Overwatch","监视","伺机徘徊+蹲守",[]],["728","Wind Rage","风之怒","入场时释放清除浓雾，空气类招式1.3倍",[]],["729","Victory Bomb","胜利炸弹","濒死时,使用威力100的火属性大爆炸.\n濒死时,以威力100的火属性大爆炸反击所有相邻的宝可梦.必定命中.无论使用者如何被击倒都会生效.",[]],["730","Razor Sharp","锋利剃刀","击中要害时，会使对方流血",[]],["731","To The Bone","刻骨铭心","击中要害伤害1.5倍，会使对方流血",[]],["732","Blade Dance","刃舞","使用舞类招式后触发50威力的叶刃",[]],["733","Taekkyeon","拳舞","所有招式都算作舞类招式",[]],["734","Ape Shift","变猿","HP低于1/2时变身，治愈自身所有状态并攻击必定击中要害",[]],["735","Know Your Place","认清位置","接触类招式使对方最后出手5回合",[]],["736","Deep Cuts","深度切割","劈砍类招式50%概率造成流血",[]],["737","Life Steal","生命偷窃","每回合偷取对方最大HP的1/10",[]],["738","Rude Awakening","大梦初醒","从睡眠状态中醒过来后，提升全能力1级且免疫睡眠",[]],["739","Teraform Zero","太晶之初","太晶甲壳+入场时清除天气和场地效果",[]],["740","Set Ablaze","恐惧之火","造成烧伤的同时也会造成恐惧",[]],["741","Breakwater","破水而出","悠游自如+慢出",[]],["742","Magical Fists","魔拳","拳类招式用特攻结算，且1.3倍",[]],["743","Cutthroat","割喉","每次入场的第一个切割类招式先制度+1",[]],["744","Sand Bender","沙漠力量","扬沙+沙之力",[]],["745","Sand Pit","沙坑","出场时使用威力20的沙穴.\n替换上场时使用威力20的沙穴攻击所有对手宝可梦,束缚它们4-5回合,使其每回合损失1/8最大HP必定命中,无视命中判定.",[]],["746","Desolate Sun","终结烈日","终结之地+食土",["免疫·水","免疫·地面","雨天免疫位","地面免疫位"]],["747","Daybreak","破晓","接触时使对手灼伤.攻击时也生效.\n使用者接触时使对手灼伤.无论攻击方还是被攻击方均会生效.",[]],["748","Energy Siphon","能量虹吸","回复造成伤害的1/4.\n回复使用者对对手造成伤害的25%.回复在伤害造成后立即生效.最少回复1点HP.",[]],["749","Reservoir","蓄水器","储水+引水",[]],["750","Neurotoxin","神经毒素","造成中毒时,降低对手的攻击、特攻和速度.\n当使对手中毒时,立即降低其攻击、特攻和速度各1级.",[]],["751","Energy Horns","能量之角","角类招式变为特殊招式，且伤害+30%",[]],["752","Rising Dough","黏性面团","入场时释放黏黏网，持续7回合",[]],["753","Crust Coat","面包外壳","对手的攻击不会击中要害，受到伤害-20%",[]],["754","Puffy","蓬松","受到的接触类招式伤害减半,但火属性招式会造成2倍伤害.\n使受到的接触类招式伤害降低50%.火属性招式对该宝可梦造成双倍伤害.与其他减伤效果乘法叠加.",[]],["755","Balloon Blitz","充气突击","充气+好斗",[]],["756","Twinkle Toes","闪光脚趾","猛踢+妖精皮肤",[]],["757","Doom Blast","厄运冲击","自身恶系招式1.35倍，造成伤害受到10%反伤",[]],["758","Brute Force","暴君之力","坚硬脑袋+舍身",[]],["759","Faraday Cage","法拉第笼","战斗盔甲 + 受到接触攻击时使用威力50的雷电笼.\n受到的伤害降低20%,与其他减伤来源乘法叠加.免疫击中要害.受到接触招式攻击时,使用雷电笼进行反击,威力50的电属性特殊招式,束缚对手4-5回合.目标每回合损失1/8最大HP,且在束缚结束前无法替换下场.",[]],["760","Acidic Slime","酸性粘液","腐蚀+毒属性获得本系加成",[]],["761","Rose Garden","罗丝花园","入场时布下两层毒钉",[]],["762","Qigong","气功","必定命中.斗争精神 + 暴走.\n使用者总是能命中目标.将所有一般属性招式转变为格斗属性招式,并为格斗属性攻击提供本系加成如果使用者是格斗属性,其格斗属性招式可以击破屏障.击倒对手时,立即从休息状态中恢复.",[]],["763","Conjurer Of Deceit","假面魔术","魔法防守+魔法镜",[]],["764","Deep Freeze","深度冻结","水和冰属性威力提升1.25倍.受到的火属性伤害减半.\n水属性和冰属性招式威力提升25%.受到的火属性招式伤害减半.与其他减伤来源乘法叠加.",["减伤·火","输出位·水、冰"]],["765","Soul Devourer","灵魂吞噬","幻痛+灵魂食者",[]],["766","Champion's Entrance","冠军登场","威吓 + 狂暴突袭.\n进入战斗时,降低所有对手宝可梦的攻击能力值1级.使用者替换上场后的第一回合,获得50%的速度加成和20%的攻击加成.",[]],["767","Presto","急速乐曲","满HP时，声音类招式先制度+1",[]],["768","Samba","桑巴","前锋 + 舞者.\n使所有踢腿类招式的威力提升30%.包括火焰球.当场上任何宝可梦使用舞蹈类招式后,该宝可梦会立即使用相同的招式每回合对每个招式触发一次.",[]],["769","JunshiSanda","拳脚相加","拳类招式或踢类招式同时算作拳类和踢类招式",[]],["770","Gladiator","猛猛斗","格斗属性招式1.3倍，HP1/3以下1.8倍",[]],["771","Forsaken Heart","弃世之心","每有精灵被打倒，物攻都会上升一段",[]],["772","Relentless","冷酷追击","弱点开发+不仁不义",[]],["773","Soothsayer","占卜大师","5回合内所有招式对该精灵都算作效果不好",[]],["774","Corrupted Mind","腐化思维","该精灵使用的所有物理招式都效果绝佳",[]],["775","Flame Coat","火焰外衣","场上非火系精灵每回合受到1/8HP的伤害+引火",[]],["776","Unown Power","未知力量","奇迹力量+觉醒力量和秘密之力都算作效果绝佳",[]],["777","Super Scope","聚焦发射器","超级发射器+炮手",[]],["778","Venom Crown","剧毒王冠","大角+毒刺",[]],["779","Blight Scale","枯萎鳞片","多重鳞片+毒刺",[]],["780","Gunman","枪手","超级发射器 + 变化招式被视为超级发射器招式.\n使脉冲、波导、波动和光环类招式威力提升30%.此外,所有变化招式都被视为超级发射器招式,可从相关特性中获得加成.",[]],["781","Hunter's Mark","猎手标记","对对方换场精灵释放40威力的缝影",[]],["782","Hemolysis","溶血","中毒的对手失去所有能力提升,且无法回复.\n当使用者使宝可梦中毒时,中毒的目标被清除所有能力提升,并且无法通过任何方式回复HP.",[]],["783","Caretaker","护理姬","治愈之心+友情防守",[]],["784","Poseidon's Dominion","波塞冬领域","入场释放潮旋",[]],["785","Two-Faced","双面形态","每回合改变形态，电系和恶系招式1.35倍，但受到10%反伤",[]],["786","Lullaby","摇篮曲","该宝可梦使用的唱歌命中率为90%.\n将唱歌的命中率提升至90%.不锁定为90%,该招式仍会受到命中率/闪避率变化的影响.",[]],["787","Cryo Architect","冷冻结构","受到水属性或冰属性的招式攻击时，攻击和物防+1",[]],["788","Glacial Rage","冰川暴怒","使用冰属性招式后触发一格50威力的暴风雪",[]],["789","Immovable Object","不可撼动","顽固+结实",[]],["790","Frenzied Phantom","狂热魅影","好斗+踩影",[]],["791","DNA Scramble","DNA重组","根据使用的招式改变形态.\n根据使用的招式改变代欧奇希斯的形态.攻击招式触发攻击形态,自我再生触发防御形态,其他变化招式触发速度形态.形态变化在攻击前发生.",[]],["792","Metallic Jaws","金属之颚","金属化 + 原始颚.\n进入战斗时,为使用者的当前属性添加钢属性.即使失去此特性,添加的钢属性在替换下场前依然保留.所有啃咬类招式攻击两次.第一击造成100%伤害,第二击造成40%伤害.每次攻击独立判定追加效果（畏缩除外）.",[]],["793","Calculative","精于算计","分析 + 脑核之力.\n当该宝可梦在目标之后行动时,攻击威力提升30%.效果绝佳的攻击威力提升35%.",[]],["794","Deadly Precision","致命精准","效果绝佳的招式必定命中,且无视特性.\n总是能对对手命中效果绝佳的攻击.允许效果绝佳的攻击无视目标的特性和先天特性,包括那些会干扰效果或降低伤害的特性.",[]],["795","Embody Aspect","体现形态","出场时速度+1.\n替换上场时,该宝可梦的速度能力值提升1级.",[]],["796","Embody Aspect","体现形态","出场时攻击+1.\n替换上场时,该宝可梦的攻击能力值提升1级.",[]],["797","Embody Aspect","体现形态","出场时防御+1.\n替换上场时,该宝可梦的防御能力值提升1级.",[]],["798","Embody Aspect","体现形态","出场时特防+1.\n替换上场时,该宝可梦的特防能力值提升1级.",[]],["799","We Will Rock You","我们将震撼你","岩石属性招式威力提升至1.3倍,HP低于1/3时提升至1.8倍.\n岩石属性招式威力提升30%,当HP低于1/3时提升80%.",[]],["800","Deviate","偏离","一般属性招式变为恶属性.恶属性招式得到强化.\n将使用者的一般属性招式变为恶属性.如果使用者是恶属性,其恶属性招式有10%的几率造成愤怒；否则,它获得恶属性的本系加成.",[]],["801","Sun's Bounty","太阳的恩赐","叶子防守 + 收获.\n在大晴天下,每回合结束时治愈所有异常状态,并且每回合结束时有50%几率回收树果,大晴天下为100%.包括用于投掷、自然之恩或被吃掉的树果.",[]],["802","Rite Of Spring","春日仪式","叶绿素 + 太阳之力.\n大晴天激活时,使用者的速度和最高的攻击能力值提升50%.",[]],["803","Headstrong","刚愎自用","出场时特防+1.\n替换上场时,该宝可梦的特防能力值提升1级.",[]],["804","Firefighter","消防员","对火属性宝可梦造成1.5倍伤害.受到火属性宝可梦攻击时,伤害减半.\n对火属性宝可梦造成1.5倍伤害,并且受到火属性宝可梦攻击时,伤害减半.此效果基于攻击方/防御方宝可梦的属性,而非招式属性.伤害减免与其他来源乘法叠加.",[]],["805","Sepia Lens","棕褐色镜片","有色眼镜 + 沙之守卫.\n结合有色眼镜和沙之守卫.攻击被抵抗时造成双倍伤害.在沙暴中,阻挡对手的先制招式,并使受到的特殊攻击伤害减半.同时像其他地面属性一样免疫沙暴伤害.",[]],["806","Super Sniper","超级狙击手","狙击手 + 攻击替换下场的对手,威力为1/2.\n击中要害时的伤害倍率从1.5倍提升至2.25倍,即额外增加50%的伤害加成.在对手替换下场前以50%的威力攻击他们,在其离开前造成伤害.",[]],["807","Woodland Curse","林地诅咒","出场时使用森林诅咒.接触时添加草属性.\n进入战斗时,对随机一名对手使用森林诅咒,为其添加草属性.当对手与使用者发生接触时,他们也会被添加草属性作为额外属性.仅影响非草属性目标.效果持续到替换下场.",[]],["808","Malodor","恶臭","接触时压制攻击者的特性.\n受到接触招式攻击时,使用者压制攻击者的特性和先天特性,直到他们替换下场.",[]],["809","Blur","模糊","受到接触攻击时,使用速度进行防御.\n当受到接触招式攻击时,该宝可梦使用其速度能力值而非防御或特防进行伤害计算.讲究围巾的效果不影响此特性.",[]],["810","Elude","规避","受到非接触攻击时,使用速度进行防御.\n            .fullDescription =COMPOUND_STRING(\"当受到非接触招式攻击时,该宝可梦使用其速度能力值而非防御或特防进行伤害计算.讲究围巾的效果不影响此特性.",[]],["811","Drake Of Rage","暴怒之龙","有色眼镜 + 暴走.\n攻击被抵抗时,伤害加倍.如果招式被抵抗（0.5倍伤害或更低）,则最终伤害乘以2倍.当使用者通过直接攻击击倒对手时,立即从休息状态中恢复.",[]],["812","Reverberate","混响","一般属性招式变为声音类招式.\n将所有一般属性招式转变为声音类招式,使其能够受益于基于声音的特性和互动.",[]],["813","Mixed Martial Arts","综合格斗","一般属性招式被视为拳和腿类招式.\n将所有一般属性招式转变为铁拳和前锋类招式,使其能够受益于相关特性和互动.",[]],["814","Strategic Pause","战略停顿","后手攻击时+2击中要害率 + 分析.\n当使用者后手攻击时,击中要害率提升2级,攻击威力提升30%.",[]],["815","Overrule","否决","击中要害时无视特性,且对被抵抗的目标造成2倍伤害.\n当该宝可梦的招式造成击中要害时,它们会无视通常会降低伤害的防御性特性,并且如果招式被抵抗,则造成双倍伤害.对于连续攻击招式,如果第一击是击中要害,则所有攻击都无视特性,否则都不无视.",[]],["816","Mental Pollution","精神污染","当自身混乱时,压制其他宝可梦的特性.\n当它陷入混乱时,对其他宝可梦施加特性压制.压制效果在这些宝可梦在场期间持续.拥有精神污染特性的宝可梦不受影响.",[]],["817","Madness Enhancement","狂化增强","在雾中陷入愤怒,愤怒时受到伤害减半.\n进入迷雾时陷入愤怒.当使用者愤怒时,所有受到的伤害降低50%,且不会受到愤怒伤害.",[]],["818","Tentalock","触手束缚","擒拿手 + 蛇缚.\n束缚类招式持续6回合而非4-5回合,并且每回合结束时的伤害提升至目标最大HP的1/6.攻击有50%几率束缚目标6回合,防止逃跑或替换.一旦被束缚,目标每在场一回合速度降低1级.",[]],["819","Serpent Bind","蛇缚","50%几率束缚,之后每回合速度降低1级.\n攻击有50%几率束缚目标4-5回合,防止逃跑或替换.一旦被束缚,目标每在场一回合速度降低1级.",[]],["820","Soul Tap","灵魂之触","在雾中,每回合结束时从对手吸取10%的HP.\n在迷雾激活时,每回合结束时,从每个在场的对手吸取其最大HP的1/10,并回复给使用者.无视替身.",[]],["821","Scarecrow","稻草人","惊吓 + 厄运.\n进入战斗时,降低所有对手宝可梦的特攻1级对手无法造成击中要害,总是造成最低伤害（85%而非85-100%）,无法触发非必定触发的追加效果,并且有5%的几率招式落空.",[]],["822","Ominous Shroud","不祥之幕","幻影 + 幻影防守.\n进入战斗时,为使用者的当前属性添加幽灵属性.即使失去此特性,添加的幽灵属性在替换下场前依然保留.当HP全满时,所有受到的攻击伤害减半.与其他减伤来源乘法叠加.",[]],["823","Chilling Presence","寒意逼人","出场时使用威力10的冰息.\n出场时使用威力10的冰息（冰属性,特殊,空气类）,攻击所有对手并降低其速度1级.",[]],["824","Frostbind","冰封禁锢","造成冻伤时也施加封印.\n当造成冻伤时,使用者也会施加封印.封印阻止目标使用其最后使用的招式,持续4回合.如果目标尚未行动,则失败.",[]],["825","Glacial Ghost","冰川鬼影","拨雪 + 雪隐.\n在冰雹中,该宝可梦的速度提升50%,并且对手的命中率降低25%.免疫冰雹伤害.",[]],["826","Tender Affection","温柔爱意","迷人之躯 + 妖精属性本系.\n受到接触招式攻击时,有50%几率使攻击者着迷（将其攻击和特攻减半）.同时为妖精属性招式提供本系加成.",[]],["827","Wonder Scale","神奇鳞片","蜕皮 + 奇迹皮肤.\n每回合结束时,该宝可梦有30%的几率治愈自身所受到的异常状态.免疫对手所有提升伤害的特性效果,亲子爱和多头龙特性除外.",[]],["828","Overzealous (N)","过度狂热 (N)","使用者的效果绝佳招式拥有+1优先度.\n不会实装.",[]],["829","Stainless Steel","不锈钢","坚壁 + 钢能力士.\n使用者无视大多数增加伤害或额外攻击次数的特性.将使用者的一般属性招式变为钢属性.如果使用者是钢属性,它抵抗幽灵和钢属性；否则,它获得钢属性的本系加成.",[]],["830","Temporal Rupture","时空断裂","时光咆哮被大幅改变.\n时光咆哮变为威力100,优先度0的攻击,将目标的特性变为慢启动（攻击、特攻和速度减半5回合）,但不再强制目标替换.",[]],["831","Grass Flute","草笛","声音类招式造成恐惧.\n声音类招式命中时造成恐惧.恐惧束缚目标2回合,使其受到的伤害增加50%.如果被吹飞等招式强制替换,目标会摆脱恐惧.",[]],["832","Hemotoxin","溶血毒素","当目标中毒时,压制其特性.\n当使用者成功使对手中毒时,压制对手的特性和先天特性.压制效果在他们替换下场后解除.",[]],["833","Harukaze","春风","设置青草场地时也设置顺风,反之亦然.\n设置顺风时也会设置青草场地,设置青草场地时也会设置顺风.如果其中一种效果已激活,则不会刷新其持续时间.",[]],["834","Toxic Surge","毒沼制造者","出场时设置剧毒场地.\n替换上场时设置剧毒场地,持续8回合（携带场地制造机时为12回合）.激活时,非毒或钢属性的接地宝可梦每回合损失1/16最大HP,毒属性招式威力提升30%,撒菱会转变为毒菱.",["场手·剧毒场地"]],["835","Atlantic Ruler","大西洋统治者","水栖居民 + 悠游自如.\n进入战斗时,为使用者的当前属性添加水属性即使失去此特性,添加的水属性在替换下场前依然保留.同时水属性招式威力提升50%.下雨天气时,速度提升50%.",[]],["836","Biofilm","生物膜","在剧毒场地中,特防提升50%.\n在剧毒场地中,使用者的特防能力值提升50%.",[]],["837","Chokehold","扼喉","束缚类招式降低对手速度并造成麻痹.\n当使用者束缚目标时,它们造成麻痹,并且在被束缚期间每回合降低其速度1级.",[]],["838","Guardian Coat","守护者外套","免疫天气伤害和粉末类招式.受到的物理伤害降低20%.\n免疫沙暴和冰雹的天气伤害,并阻挡所有粉末类招式,包括催眠粉、麻痹粉、毒粉、蘑菇孢子、棉孢子、愤怒粉、粉末和魔法粉.同时,受到的物理伤害降低20%.与其他减伤来源乘法叠加.",[]],["839","Neutralizing Fog","中和雾气","出场时使用清除浓雾.\n替换上场时使用清除浓雾,清除所有入场陷阱、屏障、神秘守护和白雾.同时降低对手的闪避率1级.",[]],["840","Poison Quills","毒刺","粗糙皮肤 + 毒刺.\n对使用接触类招式的攻击者造成其最大HP1/8的伤害.同时,无论攻击方还是被攻击方,使用接触类招式时有30%的几率使对手中毒.对于连续攻击招式,每次命中都会触发.",[]],["841","Draconic Might","龙之威仪","龙化 + 半龙.\n将所有一般属性招式转变为龙属性招式,并为龙属性招式提供本系加成.如果使用者是龙属性,其龙属性招式对妖精属性造成普通伤害.出场时,为使用者的当前属性添加龙属性即使失去此特性,添加的龙属性在替换下场前依然保留.",[]],["842","Festivities","庆典","声音类招式被视为舞蹈类招式,反之亦然.\n声音类招式也被视为舞蹈类招式,可从舞者类特性中受益.舞蹈类招式也被视为声音类招式,可从基于声音的特性中受益.",[]],["843","Fey Flight","妖精飞行","添加妖精属性并飘浮.\n进入战斗时,为使用者的当前属性添加妖精属性.即使失去此特性,添加的妖精属性在替换下场前依然保留.使用者免疫地面属性招式以及其他地面效果,如撒菱和场地状态.飞行属性招式伤害提升25%.",["免疫·地面","地面免疫位"]],["844","Best Offense","最佳攻势","神秘刀锋 + 攻击时使用20%的特防.\n锐利刀刃类招式变为特殊（造成特殊伤害并使用特攻能力值）,并在攻击计算中使用使用者20%的特防能力值.",[]],["845","Impaler","穿刺者","强大之角 + 角类招式有30%几率造成流血.\n使角和钻类攻击的威力提升30%,并且有30%的几率使目标流血流血每回合造成1/16最大HP伤害,阻止回复,并使能力等级效果无效.岩石和幽灵属性免疫流血.",[]],["846","Magus Blades","魔导剑","双持 + 最佳攻势.\n锐利刀刃类招式变为特殊（造成特殊伤害并使用特攻能力值）,并在攻击计算中使用使用者20%的特防能力值.同时,锐利刀刃类招式攻击两次,每次造成招式正常伤害的70%.追加效果在每次攻击中独立判定（畏缩除外）.",[]],["847","Lightning Born","闪电之躯","出场时添加电属性.\n进入战斗时,为使用者的当前属性添加电属性即使失去此特性,添加的电属性在替换下场前依然保留.",[]],["848","Superheavy","超重","不屈之心 + 阻挡强制替换招式.\n当陷入畏缩状态时,速度提升1级.防止因招式或红牌被强制替换.",[]],["849","World Serpent","世界之蛇","远隔 + 钳制.\n物理非接触类招式造成20%额外伤害.接触类招式有50%几率束缚目标4-5回合.",[]],["850","Lucky Wings","幸运之翼","天恩 + 巨翼.\n自身招式的追加效果触发几率加倍.使所有翅膀、风和空气类招式的威力提升30%.",[]],["851","Komodo","科莫多","添加龙属性 + 招式有30%几率造成剧毒.\n进入战斗时,为使用者的当前属性添加龙属性.即使失去此特性,添加的龙属性在替换下场前依然保留.使用者在使用任何招式命中后,有30%的几率使目标陷入剧毒连续攻击的每一击都会独立判定.",[]],["852","Envenom","施毒","招式有30%几率使目标中毒.\n使用者在使用任何招式命中后,有30%的几率使目标中毒.连续攻击的每一击都会独立判定.",[]],["853","Purple Haze","紫色迷雾","使用招式后,触发威力20的毒瓦斯.\n使用招式后,紧接着使用威力20的毒瓦斯（毒属性,特殊,20%几率中毒,对飞行属性效果绝佳）.",[]],["854","Gnashing Cannon","咬牙加农","超级发射器 + 精神咬碎.\n使脉冲、波导、波动和光环类招式威力提升30%.啃咬类招式使用特攻能力值进行伤害计算（除非另有说明,否则仍攻击目标的防御）,并造成30%额外伤害.",[]],["855","Hyper Cleanse","超净","免疫异常状态.受到的毒属性伤害减半.",["减伤·毒"]],["856","Molten Coat","熔岩外套","矿化 + 岩石属性招式有50%几率造成灼伤.",[]],["857","Royal Decree","王室敕令","女王威严 + 出场时使用一次大蛇瞪眼.\n防止使用者和它的同伴成为优先度大于0的先制招式的目标.出场时使用大蛇瞪眼,使目标麻痹.每场战斗仅触发一次.",[]],["858","Breezy Neigh","轻风嘶鸣","击倒对手时,速度提升1级.\n当该宝可梦通过直接攻击使对手濒死时,其速度能力值提升1级.",[]],["859","Dreamscape","梦境","绝对睡眠 + 捕梦人 + 造成20%额外伤害.\n该宝可梦在招式和状态判定中被视为处于睡眠状态.可以正常行动,并且免疫所有异常状态.当场上任何宝可梦处于睡眠时,招式威力加倍.攻击会对正在替换下场的睡眠中对手造成1倍伤害,在其离开前造成伤害.伤害提升20%.",[]],["860","Haste Makes Waste","欲速则不达","后攻 + 分析.\n如果该宝可梦本回合还未行动,则受到的伤害降低30%.与其他减伤来源乘法叠加.当该宝可梦在回合中替换上场时也生效.如果目标本回合已行动,则造成的伤害提升30%.",[]],["861","Hungry Maws","饥饿之颚","强壮之颚 + 杀戮之颚.\n使啃咬和颚类招式威力提升30%.使用啃咬类招式击败对手时,回复50%最大HP；使用其他招式击败时,回复25%.仅当通过直接攻击击倒目标时触发.",[]],["862","Thermal Slide","热滑","在大晴天或冰雹中,速度提升50%.\n在冰雹或大晴天下,该宝可梦的速度提升50%.同时免疫冰雹伤害.",[]],["863","Thermomancy","热力占卜","火焰占卜 + 冰霜占卜.\n将所有招式的灼伤或冻伤几率乘以5倍.与火焰之躯或冻结点特性不叠加.",[]],["864","Chuckster","强投手","每次上场一次,受到伤害减半并强制替换目标.\n每次上场,在受到接触招式攻击时,获得50%伤害减免并强制替换攻击者.与其他减伤来源乘法叠加.",[]],["865","Heat Sink","散热器","吸引火属性招式.吸收后,提升自身最高的攻击能力.\n吸引火属性招式并对其免疫.此外,受到火属性招式攻击后,自身最高的攻击能力值提升1级.",[]],["866","Relic Stone","遗石","其他参战者无法从本系加成中受益.\n在使用者在场时,所有其他宝可梦无法从属性或特性中获得本系加成.",[]],["867","Supercell","超级单体","降雨 + 电气制造者.\n出场时降下雨水并制造电气场地,持续8回合（携带潮湿岩石/场地制造机时为12回合）.水属性招式威力提升50%,火属性伤害降低50%.地面上的宝可梦不会陷入睡眠,且电属性招式威力提升30%.",[]],["868","Lightning Aspect","闪电形态","吸收电属性招式,然后最高的能力值提升1级.\n吸收电属性招式以免疫,并提升较高的攻击能力值1级.比较攻击与特攻以决定提升目标非常适合在对抗电属性攻击时进行强化,同时提供防御免疫和进攻增益.",[]],["869","Blistering Sun","灼日","终结之地 + 吹气筒.\n使用者免疫火属性招式,并在受到火属性招式攻击时回复其最大HP的25%.能够触发灼伤的招式使用时必定造成灼伤.",["免疫·火","晴天免疫位"]],["870","Molten Core","熔核","熔炉 + 吸收岩石属性招式/隐形岩.\n使用者的特攻能力值提升50%.与其他伤害加成效果乘法叠加.出场时设置极光幕,使同伴受到的物理和特殊伤害减半.持续5回合,携带光之黏土时为8回合.免疫冰雹伤害.",[]],["871","Fire Aspect","火焰形态","吸收火属性招式,且火属性招式必定灼伤.\n创造终焉大晴天,持续到使用者下场.使所有造成伤害的水属性招式无效.火属性招式获得50%威力提升.除其他原始天气外,无法被覆盖.激活与大晴天相关招式的额外效果.出场时设置3回合的顺风.使所有同伴速度加倍.",["免疫·水","免疫·火","雨天免疫位","晴天免疫位"]],["872","Aurora's Gale","极光之风","华贵之鸟 + 北风.\n所有受到的特殊攻击伤害减半.与其他减伤来源乘法叠加.",[]],["873","Ice Plumes","冰羽","受到的特殊招式伤害减半.不会加倍特防.\n受到岩石属性招式攻击或在有隐形岩的情况下替换上场时,速度提升2级.同时,吸收任何岩石属性招式或隐形岩伤害,并回复其最大HP的25%.",["减伤·特殊"]],["874","Winter Throne","寒冬王座","每回合非冰属性损失1/8HP.冰属性每回合回复1/8HP.\n所有非冰属性宝可梦每回合结束时损失1/8的最大HP.每回合结束时为冰属性宝可梦回复1/8的最大HP.",[]],["875","Energy Tap","能量之触","回复造成伤害的1/8.\n回复使用者对对手造成伤害的1/8.回复在伤害造成后立即生效.最少回复1点HP.",[]],["876","Sludge Spit","污泥喷吐","使用攻击后,紧接着使用威力35的毒液冲击.",[]],["877","Swamp Thing","沼泽生物","出场时设置沼泽誓约效果.",[]],["878","Frosty Prescence","霜寒降临","出场时使用白雾.",[]],["879","Chilling Pellets","寒冰弹","受到接触攻击时,使用威力13的冰锥.",[]],["880","Paint Shot","颜料射击","超级发射器类招式将目标的属性改变为所用招式的属性.",[]],["881","Stonecutter","石匠","化石 + 岩石属性招式无视特性.",[]],["882","Edgelord","边缘领主","每次出场第一次使用的锐利刀刃类招式获得+1优先度.击倒对手时重置.",[]],["883","Warmonger","战争贩子","使用者的岩石、钢和格斗属性招式威力提升30%.",[]],["884","Locust Swarm","蝗群","变身为蜂群形态,直到HP降至1/4或以下.",[]],["885","Revelation","天启","变身为天启形态,直到HP降至1/4或以下.",[]],["886","Curse of Famine","饥荒诅咒","吞噬场地,回复HP,并提升一项防御能力.",[]],["887","Crystalline Armor","水晶铠甲","反弹能力降低,并免疫击中要害.",[]],["888","Soul Harvest","灵魂收割","每只濒死的宝可梦使你的进攻能力和特防提升5%.",[]],["889","Thick Blubber","厚脂","受到的火和冰属性伤害降低75%,但速度减半.",[]],["890","Craving","渴望","每回合结束时随机吃一个树果.\n每回合结束时随机吃一个以下树果：利木果、文柚果、枝荔果、龙晴果、沙鳞果、龙火果、杏仔果、兰萨果、星桃果、嘉珍果或随机一个危机回复树果.",[]],["891","Rat King","鼠王","种族值总和低于400的同伴,其能力值提升50%.",[]],["892","Crispy Cream","酥脆奶油","受到接触攻击时,有30%几率造成灼伤或冻伤.",[]],["893","Deep Fried","油炸","出场时召唤一片火海.",[]],["894","Food Lovers","美食家","热情好客 + 友情防守.",[]],["895","Lunar Wrath","月之怒","使用幽灵属性招式后,紧接着使用威力50的暗影之光.",[]],["896","Spyware","间谍软件","根据对手的强项,大幅提升一项能力.",[]],["897","Virus","病毒","电属性招式有30%的几率同时造成中毒.",[]],["898","Power Leak","电力泄漏","受到攻击时,设置电气场地.",[]],["899","Backup Power","备用电源","在电气场地中濒死后,复活一次,HP为25%.",[]],["900","Sand Fiend","沙之魔","沙之力 + 沙之守卫.",[]],["901","Moustache","胡子","卷发 + 持久力.",[]],["902","Depth Explorer","深度探险家","旷野探险家 + 发光.",[]],["903","Dune Veil","沙丘帷幕","沙漠披风 + 自给自足.\n在沙暴激活时,所有同伴免疫异常状态和来自敌人招式的追加效果.每回合结束时回复该宝可梦1/16的最大HP.",[]],["904","Strong Foundation","坚实基础","受到的水和地面属性伤害减半,且不会被强制替换.",["减伤·水","减伤·地面"]],["905","Fog Machine","造雾机","受到攻击时,设置诡异迷雾.",[]],["906","Drop Blocks","落块","受到攻击时,设置撒菱.",[]],["907","Laser Drill","激光钻","角类招式有50%几率造成灼伤.",[]],["908","Lightsaber","光剑","添加火属性.锐利刀刃类招式有25%几率造成灼伤或麻痹.",[]],["909","Loose Thorns","松散荆棘","受到接触攻击时,设置蔓延荆棘.",[]],["910","Turf War","地盘争夺","出场时破坏场地并提升最高的能力值.",[]],["911","Greedy","贪婪","失去物品时使用偷窃.",[]],["912","Musical Notes","音符","变化招式变为声音类.",[]],["913","Strikeout","三振出局","如果对手连续3回合不攻击,则强制其替换下场.",[]],["914","Home Run","本垒打","造成击中要害时,每回合一次提升你最低的三项能力.",[]],["915","Bruiser","壮汉","出场时添加格斗属性.",[]],["916","Narcissist","自恋者","当一项能力被降低时,大幅提升双攻.",[]],["917","Let's Dance","来跳舞吧","出场时使用摇摆舞,使全场混乱.",[]],["918","Dragonfruit","火龙果","半龙 + 粗糙皮肤.",[]],["919","Lead Claws","铅爪","坚硬爪子 + 矿化.",[]],["920","Rocky Exterior","岩石外表","出场时添加岩石属性.",[]],["921","Flawless Precision","无瑕精准","致命精准 + 致命精准.",[]],["922","Empress","女皇","女王威严 + 斗争心.",[]],["923","Mashed Potato","土豆泥","对敌人施加蜜糖炸弹效果,持续3回合.",[]],["924","Taste the Rainbow","品味彩虹","出场时召唤彩虹誓约效果.",[]],["925","Rainbow Scales","彩虹鳞","火鳞 + 品味彩虹.",[]],["926","Hypnotic Touch","催眠之触","接触攻击有20%几率造成睡眠.攻击时也生效.\n接触攻击有20%几率造成睡眠攻击时也生效.",[]],["927","Wings of Pestilence","疫病之翼","每次攻击有20%几率造成流血,10%几率施加诅咒.",[]],["928","Hydra","九头蛇","多头龙 + 傲慢.\n每当使用者通过直接攻击击倒对手时,其特攻能力值提升1级.根据头数,每次攻击2-3次.2头总倍率1.25倍,3头总倍率1.35倍.",[]],["929","Sundae","圣代","降雪 + 冰冻之躯.",[]],["930","Ice Picks","冰镐","坚硬爪子 + 拨雪.",[]],["931","Hammer Fist","锤拳","拳类和锤类招式威力提升25%.",[]],["932","Drakelp Head","龙首藻","减弱受到的第一次攻击,并降低对手的攻击.",[]],["933","Polarity","极性","使己方队伍最高的能力值提升30%.",[]],["934","Mach 3","3马赫","致命精准 + 滑流.",[]],["935","Raging Storm","暴风雨","在雨中,自身最高的攻击能力提升至1.5倍.",["天气受益·雨天"]],["936","Sumo Guard","相扑守卫","主宰 + 厚脂肪.",[]],["937","Sumo Wrestler","相扑手","每两个回合结束时,使用威力20的巴投.",[]],["938","Cosmic Wings","宇宙之翼","飞行属性招式变为妖精属性.",[]],["939","Cosmic Dust","宇宙尘埃","魔法防守 + 宇宙迷乱.",[]],["940","Cool Exit","酷炫离场","在你的第二个回合结束时使用冰冷欢迎.",[]],["941","Devious Present","恶作剧礼物","冰属性和投掷类招式威力提升50%.",[]],["942","Christmas Nightmare","圣诞噩梦","在冰雹中,敌人每回合损失1/8HP.",[]],["943","Sap Trap","树液陷阱","每回合结束时降低对手速度.降至-3时束缚目标.",[]],["944","Dead Bark","枯树皮","添加幽灵属性.受到的伤害降低15%.如果效果绝佳,则降低30%.",[]],["945","Chainsaw","链锯","锐利刀刃攻击降低目标防御1级.",[]],["946","Galeforce Wings","飓风之翼","飞行属性招式获得+1优先度.",[]],["947","Echolocation","回声定位","在雾中,造成20%额外伤害且必定命中.",[]],["948","Massive Pelt","厚重毛皮","卷发 + 毛茸茸.",[]],["949","I Am Steve","我是史蒂夫","出场时使用背水一战.",[]],["950","Tangled Tails","缠尾","识相点 + 擒拿手.\n使用接触类招式命中后,使目标在5回合内无论优先度、速度或其他效果如何,总是最后行动.效果不会叠加,也不会对已受影响的目标刷新.束缚类招式持续6回合而非4-5回合,并且每回合结束时的伤害提升至目标最大HP的1/6.",[]],["951","Foamy Web","泡沫网","出场时设置无法移除的黏黏网.持续5回合.\n使用者进入战斗时,在对手场上设置黏黏网.持续5回合,使任何替换上场的接地宝可梦速度降低1级.如果对手场上已有黏黏网,则无法激活.",[]],["952","Sharp Talons","锐爪","踢腿类招式有50%几率造成流血.",[]],["953","Zen Garden","禅意花园","随机设置青草或精神场地.\n出场时随机设置青草或精神场地,几率各50%.携带青草种子必定触发青草场地,携带精神种子必定触发精神场地.",[]],["954","Tummyache","胃痛","厚脂肪 + 腐蚀.",[]],["955","Hypnotic Trance","催眠恍惚","催眠术必定命中,且同时造成混乱.",[]],["956","Brain Overload","大脑过载","受到攻击时,设置精神场地.",[]],["957","Brain Mass","脑容量","HP全满时,受到的伤害减半.",["减伤·满血"]],["958","Chestnut Shield","栗子盾","坚不可摧 + 防弹.",[]],["959","Chestnut Axe","栗子斧","锐利刀刃 + 草属性招式获得锐利刀刃加成.",[]],["960","Giant Shuriken","巨型手里剑","水手里剑攻击一次,威力100,且+1击中要害率.",[]],["961","Witch Broom","女巫扫帚","极度好战 + 悬浮.",[]],["962","Angelic Wings","天使之翼","棱镜鳞片 + 巨翼.",[]],["963","Wrestle Showman","摔跤表演家","飞身重压威力+10,并造成挑衅效果.",[]],["964","Lucha Libre","自由式摔跤","棱镜装甲 + 不服输.",[]],["965","Fire Ruler","火之统治者","王之怒 + 火焰盾.\n当使用者或其同伴的能力被降低时,提升攻击和防御.受到效果绝佳的招式攻击时,伤害降低35%.与其他减伤来源乘法叠加.",[]],["966","Chandelier","枝形吊灯","发光 + 火焰占卜.",[]],["967","Foggy Eye","雾眼","在雾中,幽灵属性招式威力提升50%,并且抵抗幽灵属性招式.",[]],["968","Toxic Shell","毒壳","硬壳盔甲 + 毒刺.",[]],["969","Hand Barnacles","手藤壶","多头龙 + 水属性本系.",[]],["970","Voltron","战神金刚","金属化 + 战斗盔甲.",[]],["971","Fire's Wrath","火之怒","威吓 + 惊吓 + 非接触招式有10%灼伤几率.",[]],["972","Emperor's Wrath","帝王之怒","王之怒 + 后之哀.",[]],["973","Lepidopteran","鳞翅目","虫之预感 + 纯朴.",[]],["974","Break it Down","分解","使用攻击后,紧接着使用威力20的急速轮转.",[]],["975","Talon Trap","爪钩陷阱","接触时有50%几率束缚目标.如果本回合刚上场,则几率为100%.\n无论攻击方还是被攻击方,发生接触时有50%几率束缚对手,效果类似于夹住.如果使用者本回合刚替换上场或通过Mega进化等方式获得此特性,则几率提升至100%.",[]],["976","Backstreet Boy","后街男孩","前锋 + 踢腿类招式被视为舞蹈类招式,反之亦然.",[]],["977","Backflip","后空翻","使用舞蹈类招式后,紧接着使用威力50的逐步击破.",[]],["978","Crushing Jaw","粉碎之颚","强壮之颚 + 啃咬类招式有50%几率降低防御.",[]],["979","Eternal Flower","永恒之花","使其他超级进化宝可梦的能力值降低20%.",[]],["980","Nihil Blaster","虚无一击","气场破坏 + 超级发射器.",[]],["981","Hollow Ice Zone","冰窟地带","冰属性招式施加冰雕状态,然后使使用者替换下场.\n使用者的冰属性招式对目标施加冰雕状态,使其变为冰属性,失去所有抗性和冻伤免疫.如果施加了冰雕状态,使用者会替换下场.",[]],["982","Cryostasis","低温休眠","冰霜占卜 + 冻伤造成畏缩.",[]],["983","Overcast","阴天","低能见度 + 出场时设置白雾.",[]],["984","Flower Necklace","花项链","在青草场地中,该宝可梦的特防提升至1.5倍.",["场地受益·青草场地"]],["985","Mega Drill","巨型钻头","强大之角 + 所有钻类招式威力提升30%.",[]],["986","Mucus Membrane","黏液膜","受到的攻击伤害降低30% + 黏滑.",[]],["987","Rain Shroud","雨幕","在雨中,闪避率提升30%.",[]],["988","Curlipede","卷曲蜈蚣","我们滚吧 + 盘卷.",[]],["989","Storm Cloud","积雨云","出场时降下雨水,持续8回合.获得电属性本系加成.",["天气手·雨"]],["990","Waterborne","水传播","水生 + 适应力.",[]],["991","Resilience","韧性","每当HP低于1/2时,回复1/4的最大HP.",[]],["992","Going Berserk","进入狂暴","怒火冲天 + 暴走.",[]],["993","Thunder Clouds","雷云","使用特殊招式后,发射威力35的十万伏特.",[]],["994","Unrelenting","不屈不挠","所有攻击招式可以攻击2-5次.",[]],["995","Elemental Aegis","元素庇护","受到的火、电和水属性招式伤害减半.",[]],["996","Aegis Ward","守护结界","受到的恶、幽灵和超能力属性招式伤害减半.",[]],["997","Shattered Armor","破碎铠甲","战斗盔甲 + 废料场.",[]],["998","Acid Reflux","胃酸反流","受到伤害时,使用威力20的溶解液.",[]],["999","Ghost Frenzy","幽灵狂乱","极度好战 + 噬魂.",[]],["1000","Survivor Bias","幸存者偏差","效果不好的招式无法造成濒死.",[]],["1001","Bandit","强盗","拾荒者 + 技术高手.",[]],["1002","Fortress","堡垒","过滤 + 战斗盔甲.",[]],["1003","Bird of Prey","猛禽","健壮胸肌 + 胆量.",[]],["1004","Feathercoat","羽衣","受到的所有攻击伤害降低10%.被抵抗时降低20%.",[]],["1005","Power Outage","停电","第一次电属性攻击威力提升2倍,之后失去电属性.",[]],["1006","Electro Booster","电击助推器","出场时使用电磁飘浮.",[]],["1007","Current Crash","电流冲击","舍身 + 雷召.",[]],["1008","Daredevil","冒失鬼","使用反伤招式后,攻击+1.反伤伤害减半.",[]],["1009","Frost Dragon","霜龙","使用龙或冰属性招式后,触发威力50的暴风雪.",[]],["1010","Thermal Entropy","热熵","热交换 + 耐热.",[]],["1011","Sinister Claws","阴险之爪","神秘刀锋 + 锐利刀刃类招式降低特防.\n锐利刀刃类招式造成1.3倍伤害,变为特殊招式,使用特攻能力值并攻击特防.同时降低目标特防1级（每回合每个目标最多一次）.",[]],["1012","Petal Shield","花瓣盾","出场时防御提升至最大.受到攻击时防御降低1级.\n出场时防御提升至+6级.受到攻击后防御降低1级.连续攻击会多次降低防御.",[]],["1013","Mob Boss","黑帮老大","恐怖 + 偏离.\n出场时降低所有对手的特攻2级将使用者的一般属性招式变为恶属性.如果使用者是恶属性,其恶属性招式有10%的几率造成愤怒；否则,它获得恶属性的本系加成.",[]],["1014","Ghost Pepper","幽灵辣椒","草属性招式有30%几率造成灼伤.",[]],["1015","Droideka","毁灭者","耐热 + 战斗盔甲.",[]],["1016","3 > 1","3 ョ 1","多头龙 + 激流.",[]],["1017","Icicle Fist","冰柱拳","铁拳 + 拳类招式有30%几率造成冻伤.",[]],["1018","Abominable Monster","可憎怪物","在冰雹中,特防提升1.5倍.\n在冰雹中,使用者的特防能力值提升50%.此提升适用于所有依赖防御的效果.",["天气受益·冰雹"]],["1019","Wind Chimes","风铃","扩音器 + 受到攻击时以威力30的高音反击.",[]],["1020","Unstable Core","不稳定核心","动力核心 + 引爆.",[]],["1021","Aura Armor","气场铠甲","受到的伤害降低35%.",[]],["1022","Deflect","偏斜","受到攻击时以威力20的真空波反击.受到的伤害降低20%.",[]],["1023","Overwhelming Mind","压倒性思维","超能力属性招式威力提升至1.3倍,HP低于1/3时提升至1.8倍.",[]],["1024","Duality","二元性","穿透 + 好胜.",[]],["1025","Foul Energy","死神拥抱","坚硬爪子 + 邪恶能量.",["输出位·恶"]],["1026","Reaper's Embarce","邪恶能量","恶属性招式威力提升至1.2倍,HP低于1/3时提升至1.5倍.",[]],["1027","Jungle Fever","丛林热","在青草场地中,该宝可梦的速度提升至1.5倍.\n丛林热在青草场地激活时,该宝可梦的速度能力值提升50%.场地开始时立即生效,场地结束时加成消失.",[]],["1028","King of the Jungle","丛林之王","穿透 + 对草属性宝可梦造成1.5倍伤害.",[]],["1029","Warrior's Spear","勇士之矛","强大之角 + 斗争精神.",[]],["1030","Sleek Scales","","The Pokémon uses +15% of its Speed when defending.",[]],["1031","Rock Armor","","Rocky Exterior + takes 10% less damage from attacks.",[]],["1032","Smoldering Wood","","Raw Wood + Flame Body.",[]],["1033","Slime Mold","","Sticky Hold + Gooey.",[]]];
