ERDATA["glossary"]=[{"key":"weather_rain","term":"Rain (Rain Dance / Drizzle)","zh":"雨天","body":"水属性招式威力×1.5（+50%）、火属性×0.5。ER v2.65 按天气标记分档：TEMPORARY|PRIMAL=×1.5、PERMANENT=×1.2（WCONF.weatherBoostByFlag）；手动天气只写 TEMPORARY 槽 ⇒ 手动与特性同档 ×1.5，「特性+20%」旧口径已废（WCONF.abilityBoost 废弃）。持续 8 回合（WCONF.manualDurTurns / abilityDurTurns），持天气岩石延长至 12（WCONF.rockTurnsManual / rockTurnsAbility）。暴风、打雷等招在雨天下必中。【来源档位：v2.65 源码实证】"},{"key":"weather_sun","term":"Sun (Sunny Day / Drought)","zh":"晴天","body":"火属性招式威力×1.5、水属性×0.5（WCONF.weatherBoostByFlag，手动=特性同档）。日光束/日光刃在晴天下无需蓄力。持续 8 回合（WCONF.manualDurTurns / abilityDurTurns）、岩石延长 12 回合（WCONF.rockTurnsManual / rockTurnsAbility）。太阳之力94：晴天下最高攻击项×1.5，但每回合掉血。【来源档位：v2.65 源码实证】"},{"key":"weather_sand","term":"Sandstorm","zh":"沙暴","body":"回合末对非岩/地/钢属性宝可梦造成 1/16 伤害；岩石属性宝可梦特防×1.5。持续 8 回合、岩石延长 12 回合（WCONF.manualDurTurns / abilityDurTurns / rockTurnsManual / rockTurnsAbility）。拨沙受益者在沙暴中速度×2。【来源档位：回合数与分档 v2.65 源码实证；岩石特防×1.5 属原版口径，未列入 v2.65 实证清单】"},{"key":"weather_hail","term":"Hail / Snow","zh":"冰雹（雪天）","body":"冰属性宝可梦防御×1.5（源码 S9）；暴风雪必中；回合末对非冰系造成 1/16 伤害。持续 8 回合、岩石延长 12 回合（WCONF.manualDurTurns / rockTurnsManual）。【来源档位：v2.65 源码实证】"},{"key":"weather_manual","term":"Manual Weather Moves","zh":"手动天气招式","body":"求雨240 / 大晴天241 / 沙暴201 / 冰雹258。基础 8 回合 —— v2.65 源码常量 WEATHER_DURATION = 8（WCONF.manualDurTurns），**无 5 回合档**（changelog v1.5「still 5 turns」与之冲突，已登记，取源码）。增伤与特性同档（WCONF.weatherBoostByFlag）。【来源档位：v2.65 源码实证】"},{"key":"weather_ability","term":"Weather Abilities","zh":"特性天气","body":"降雨2 / 日照70 / 扬沙45 / 降雪117，出场即触发。持续 8 回合（WCONF.abilityDurTurns）；viaAbility 形参不影响时长与倍率（WCONF.abilityBoost 已废弃）。【来源档位：v2.65 源码实证】"},{"key":"weather_rock","term":"Weather Rocks","zh":"天气岩石","body":"湿润岩石298 / 炽热岩石297 / 沙沙岩石296 / 冰冷岩石295：天气 8 → 12 回合（WCONF.rockTurnsManual / rockTurnsAbility，源码 WEATHER_DURATION_EXTENDED = 12）。原版「手动 5→8」口径已废。【来源档位：v2.65 源码实证】"},{"key":"terrain_boost","term":"Terrain Boost","zh":"场地增伤","body":"场地内对应属性招式威力×1.3（+30%）（WCONF.terrainBoost）。来源 B_TERRAIN_TYPE_BOOST = GEN_8 + 伤害段 MUL_MODIFIER(&modifier, 1.3)，含剧毒场地。本项目模板旧文案「+30%」数值正确。【来源档位：v2.65 源码实证，定稿】"},{"key":"terrain_dur","term":"Terrain Duration","zh":"场地持续","body":"8 回合（WCONF.terrainDurTurns，源码 TERRAIN_DURATION = 8）；持场地延展器 12 回合（WCONF.terrainExtenderTurns，TERRAIN_DURATION_EXTENDED = 12，即 +4）。【来源档位：v2.65 源码实证】"},{"key":"terrain_extender","term":"Terrain Extender","zh":"场地延展器","body":"道具326。场地 8 → 12 回合（+4）（WCONF.terrainExtenderTurns）。初版口径 11（+3，按原版百科类推）已废。【来源档位：v2.65 源码实证】"},{"key":"terrain_electric","term":"Electric Terrain","zh":"电气场地","body":"电属性招式×1.3（WCONF.terrainBoost）；场上宝可梦免疫睡眠。【来源档位：v2.65 源码实证】"},{"key":"terrain_psychic","term":"Psychic Terrain","zh":"精神场地","body":"超能力属性招式×1.3（WCONF.terrainBoost）；场地内先制招式失效（克制偷袭/突袭）。【来源档位：v2.65 源码实证】"},{"key":"terrain_grassy","term":"Grassy Terrain","zh":"青草场地","body":"草属性招式×1.3（WCONF.terrainBoost）；场上宝可梦每回合回复 HP。青草滑梯在场地内必定先手。【来源档位：增伤 v2.65 源码实证；回合末回复量属原版口径】"},{"key":"terrain_misty","term":"Misty Terrain","zh":"薄雾场地","body":"妖精属性招式增伤（同场地档 WCONF.terrainBoost）；全队免疫异常状态；「龙系伤害减半」已在 v2.65.3b 移除。【来源档位：增伤 v2.65 源码实证；龙伤减半移除见 官方 changelog v2.65.3b】"},{"key":"terrain_toxic","term":"Toxic Terrain","zh":"剧毒场地","body":"毒属性招式×1.3（WCONF.toxicTerrain.boost / WCONF.terrainBoost）；回合末对场上宝可梦造成 1/16 伤害（WCONF.toxicTerrain.dmgFraction）；豁免为「毒或钢属性全类型豁免（不看接地）」（WCONF.toxicTerrain.immunity）。持续 8 回合、延展器 12（WCONF.toxicTerrain.durTurns）。设置手：毒沼制造者 834 Toxic Surge。【来源档位：v2.65 源码实证】"},{"key":"hazard_spikes","term":"Spikes","zh":"撒菱","body":"最多 3 层；换入伤害 1/8（1层）·1/6（2层）·1/4（3层），仅对「接地」宝可梦生效（WCONF.hazardRules.spikes = {maxLayers:3, dmg:[1/8,1/6,1/4], groundedOnly:true}）。源码 spikesDmg=(5-层数)*2、maxHP/spikesDmg。【来源档位：v2.65 源码实证 S10】"},{"key":"hazard_stealthrock","term":"Stealth Rock","zh":"隐形岩","body":"单层；伤害按岩石对目标的克制倍率：4×弱点 1/2、2×弱点 1/4、中性 1/8、2×抵抗 1/16、4×抵抗 1/32（WCONF.hazardRules.stealthRock.dmgByRockEff）。【来源档位：Psypoke / 原版口径；ER 未另给数值】"},{"key":"hazard_toxicspikes","term":"Toxic Spikes","zh":"毒菱","body":"最多 2 层：1 层中毒、2 层剧毒；钢属性免疫、接地毒属性宝可梦可吸收全部层数（WCONF.hazardRules.toxicSpikes = {maxLayers:2, steelImmune:true, groundedPoisonAbsorbs:true}）。【来源档位：原版口径】"},{"key":"hazard_stickyweb","term":"Sticky Web","zh":"粘网","body":"单层；换入者速度 −1 级；飞行属性 / 飘浮 / 气球持有者免疫（WCONF.hazardRules.stickyWeb）。【来源档位：原版口径】"},{"key":"hazard_clear","term":"Hazard Removal","zh":"除钉范围","body":"高速旋转229：清**自身侧**全部钉子，并提升自身速度+1。清除浓雾432：清**双方**钉子，墙类（反射壁/光墙/白雾/极光幕/神秘守护/黑雾）**仅对手侧**，并降低目标闪避 1 级；**不清场地地形**（WCONF.defogRapidSpin）。【来源档位：v2.65 源码实证】"},{"key":"status_para","term":"Paralysis","zh":"麻痹","body":"速度×0.5（WCONF.paraSpeed，源码整除以 2）；每回合 25% 概率完全无法行动（WCONF.paraFullChance，Random()%4==0）。电属性宝可梦免疫麻痹。12.5%（Pokémon Champions 口径）属 v2.65 之后版本，本表不采用。【来源档位：v2.65 源码实证】"},{"key":"status_frostbite","term":"Frostbite","zh":"冻伤","body":"每回合末受到 1/16 最大 HP 伤害（WCONF.frostbite.dmgFraction），且特攻×0.5（WCONF.frostbite.spAtkMult）；替代原版「冰冻」。「冰雹中触发概率×3」两 pin 均未找到 ⇒ 退回待实测（WCONF.frostbite.hailChanceMult 待实测；唯一确证的概率加成是 Cryomancy ×5）。【来源档位：1/16 与特攻减半 v2.65 源码实证；hail×3 待实测】"},{"key":"status_burn","term":"Burn","zh":"烧伤","body":"每回合末受到 1/16 最大 HP 伤害，且物攻×0.5。【来源档位：原版口径】"},{"key":"status_toxic","term":"Badly Poisoned","zh":"剧毒","body":"每回合末伤害逐回合递增（1/16 → 2/16 → …），直至换下。【来源档位：原版口径】"},{"key":"status_sleep","term":"Sleep","zh":"睡眠","body":"若干回合内无法行动；被击中不会醒来，需自然醒或特定招式唤醒。【来源档位：原版口径】"},{"key":"boost_dance","term":"Stat Boost Moves","zh":"强化招式","body":"剑舞14 物攻+2 / 龙之舞349 物攻+速度+1 / 蝶舞483 特攻+特防+速度+1 / 诡计417 特攻+2 / 破壳504 攻·特攻·速+2 但防·特防−1。ER 个体默认满值，强化后收益最大化。【来源档位：招式数据】"},{"key":"priority","term":"Priority","zh":"先制","body":"先制度高者先行动；恶作剧之心给变化招式 +1 先制；击掌奇袭252 首回合必定先手并造成畏缩。空间（戏法空间）内先制招式仍照常先手。【来源档位：招式/特性数据】"},{"key":"trickroom","term":"Trick Room","zh":"戏法空间","body":"5 回合内速度越慢者越先行动；先制 −7（WCONF.trickroomPrio，数据驱动 gameData.moves[433].prio）。**实际回合数存疑**：文案/数据均写 5，但源码 TRICK_ROOM_DURATION 5 + 施放回合不递减 ⇒ 机械推算 6 个回合时段，冲突未消除（WCONF.trickroomTurns 待实测）。【来源档位：先制属数据实证；回合数待实测】"},{"key":"tailwind","term":"Tailwind","zh":"顺风","body":"全队速度×2，持续 4 个回合时段（WCONF.tailwindTurns = 3 + 施放当回合不递减）。自动顺风（Air Blower / North Wind 等）常量同为 3（WCONF.autoTailwindTurns）⇒ 实际同为 4 时段，与手动的差别不在时长。【来源档位：v2.65 源码实证】"},{"key":"charge","term":"Charging Moves","zh":"蓄力招式","body":"两回合招：第一回合蓄力、下一回合发动（日光束76/日光刃632、飞空19、挖洞91、潜水291、神鸟猛攻143 等）。晴天（日光束/日光刃）或雨天（如部分电招）可免蓄力。【来源档位：招式数据】"},{"key":"recharge","term":"Recharge","zh":"僵直（再蓄力）","body":"破坏光线63 / 终极冲击416 / 爆裂燃烧307 / 水炮308 / 疯狂植物338 等：使用后下一回合自身无法行动。【来源档位：招式数据】"},{"key":"recoil","term":"Recoil","zh":"反伤","body":"闪焰冲锋394 / 勇鸟猛攻413 / 舍身冲撞38 等反弹造成伤害的 1/3；部分招式 1/4（伏特攻击344）或 1/2（双刃头锤457 / 破灭之光617 等）。【来源档位：招式数据】"},{"key":"ate","term":"-ate Abilities","zh":"-ate 属性转换","body":"一般属性招式转为指定属性（Pixilate182→妖精 / Refrigerate174→冰 / Aerilate184→飞行 / Galvanize206→电 / Hydrate315→水 / Intoxicate325→毒 / Normalize96→一般）。宏族**×1.0**（WCONF.ABI_ATE.multiplier，10% 加成已移除）；转换后招式获得 STAB ×1.5（吃适应力可达 ×2.0，WCONF.stabConvert=true）。特例 ×1.1：Normalize96 / Crystallize280（岩石→冰） / Superconductor659（钢→电）（WCONF.ABI_ATE.specialMultiplier）。家族 Pin A 25 / Pin B 27 条。【来源档位：v2.65 源码实证】"},{"key":"stab","term":"STAB","zh":"本系加成","body":"招式属性与自身属性一致时威力 ×1.5；适应力91 提升至 ×2.0。Relic Stone 特性在场时 STAB 被压成 ×1.0。【来源档位：v2.65 源码实证（StabMultiplierInHalves：3=×1.5、4=×2.0）】"},{"key":"relic_stone","term":"Relic Stone","zh":"圣石（STAB 压制）","body":"该特性（或宝可梦）在场时，场上 STAB 计算被压成 ×1.0（源码返回 2）。【来源档位：v2.65 源码实证 S3】"},{"key":"recover","term":"Recovery Moves","zh":"回复类招式","body":"自我再生105 / 偷懒303 / 羽栖355 / 终极吸取202 等回复最大 HP 的一半；晨光234 / 光合作用235 / 月光236 回复量随天气变化（晴天最高约 2/3）。【来源档位：回复半血与天气依赖属原版口径】"},{"key":"weatherball","term":"Weather Ball","zh":"天气球","body":"天气生效时改变属性（随天气）并威力翻倍。【来源档位：原版口径；ER 未单独实证】"},{"key":"intimidate_guard","term":"Intimidate Immunity","zh":"防威吓","body":"不被威吓降低物攻的特性：不服输（被降能力时反升物攻2级）、自信过度153、胆量 等。【来源档位：特性数据】"},{"key":"weather_double","term":"Weather Double Boost","zh":"天气增伤翻倍","body":"该特性（S2）使天气增伤叠加为 ×1.5 × ×1.5 = ×2.25（在 WCONF.weatherBoostByFlag 之上再乘），并可使雨天火属性从 ×0.5 变为 ×1.5。【来源档位：v2.65 源码实证 S2】"},{"key":"hazard_bug","term":"Stealth Rock Bug (Beta2)","zh":"隐形岩非首铺疑似失效","body":"v2.65 Beta2 社区报告：隐形岩若不是首个布下的钉子疑似失效（其它钉子正常）。无源码/官方结论 ⇒ 引擎判钉时不假设隐形岩必然生效，输出风险提示。【来源档位：C 档待实测】"}];
